fn rubber_band_may_start(cells: &[(PathBuf, Rect)], pointer: egui::Pos2) -> bool {
    !cells.iter().any(|(_, rect)| rect.contains(pointer))
}

fn rubber_band_selection(
    cells: &[(PathBuf, Rect)],
    selection_rect: Rect,
    existing: &HashSet<PathBuf>,
    modifiers: egui::Modifiers,
) -> HashSet<PathBuf> {
    let intersecting = cells
        .iter()
        .filter(|(_, rect)| rect.intersects(selection_rect))
        .map(|(path, _)| path.clone())
        .collect::<HashSet<_>>();

    if modifiers.shift {
        existing.union(&intersecting).cloned().collect()
    } else if modifiers.command || modifiers.ctrl {
        existing
            .symmetric_difference(&intersecting)
            .cloned()
            .collect()
    } else {
        intersecting
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CreationKind {
    File,
    Folder,
}

fn build_creation_command(
    kind: CreationKind,
    parent: &Path,
    name: &str,
) -> Result<FileCommand, String> {
    validate_creation_name(name)?;
    if std::fs::symlink_metadata(parent.join(name)).is_ok() {
        return Err("An entry with that name already exists.".to_string());
    }

    Ok(match kind {
        CreationKind::File => FileCommand::CreateFile {
            parent: parent.to_path_buf(),
            name: name.to_string(),
        },
        CreationKind::Folder => FileCommand::CreateFolder {
            parent: parent.to_path_buf(),
            name: name.to_string(),
        },
    })
}

fn creation_command_from_input(
    kind: CreationKind,
    raw: &str,
    parent: &Path,
) -> Result<FileCommand, String> {
    let name = raw
        .split_once(char::is_whitespace)
        .map(|(_, remainder)| remainder.trim())
        .unwrap_or("");
    build_creation_command(kind, parent, name)
}

fn creation_modal_width(viewport_width: f32) -> f32 {
    (viewport_width - 32.0).clamp(320.0, 400.0)
}

fn created_path_for_successful_command(cmd: &FileCommand, succeeded: bool) -> Option<PathBuf> {
    if !succeeded {
        return None;
    }
    match cmd {
        FileCommand::CreateFile { parent, name } | FileCommand::CreateFolder { parent, name } => {
            Some(parent.join(name))
        }
        _ => None,
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum CreationCompletionTarget {
    MainListing {
        created_path: PathBuf,
    },
    MillerListing {
        parent: PathBuf,
        created_path: PathBuf,
    },
}

fn creation_completion_target(
    cmd: &FileCommand,
    succeeded: bool,
    current_dir: &Path,
    displayed_dir: &Path,
) -> Option<CreationCompletionTarget> {
    let (parent, created_path) = match cmd {
        FileCommand::CreateFile { parent, .. } | FileCommand::CreateFolder { parent, .. } => {
            (parent, created_path_for_successful_command(cmd, succeeded)?)
        }
        _ => return None,
    };
    if parent != displayed_dir {
        return None;
    }
    if parent == current_dir {
        Some(CreationCompletionTarget::MainListing { created_path })
    } else {
        Some(CreationCompletionTarget::MillerListing {
            parent: parent.clone(),
            created_path,
        })
    }
}

