#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct SettingsPlatformCapabilities {
    terminal_launcher_visible: bool,
    system_locate_controls_visible: bool,
    privilege_backend: &'static str,
    scheduler_name: &'static str,
}

fn settings_platform_capabilities(is_windows: bool) -> SettingsPlatformCapabilities {
    if is_windows {
        // The current Windows launcher writes a batch file in the home directory,
        // but does not register that directory on PATH. Do not present it as a
        // usable terminal command until that integration actually exists.
        SettingsPlatformCapabilities {
            terminal_launcher_visible: false,
            system_locate_controls_visible: false,
            privilege_backend: "UAC",
            scheduler_name: "Windows Task Scheduler",
        }
    } else {
        SettingsPlatformCapabilities {
            terminal_launcher_visible: true,
            system_locate_controls_visible: true,
            privilege_backend: "polkit",
            scheduler_name: "systemd --user or crontab",
        }
    }
}

fn graphics_renderer_reason_label(reason: GraphicsRendererReason) -> &'static str {
    match reason {
        GraphicsRendererReason::CommandLineOverride => "command-line OpenGL override",
        GraphicsRendererReason::PersistedNativePreference => "your Native preference",
        GraphicsRendererReason::PersistedCompatibilityPreference => {
            "your OpenGL compatibility preference"
        }
        GraphicsRendererReason::RemoteSession => "a Remote Desktop session was detected",
        GraphicsRendererReason::VirtualOrProblemAdapter => {
            "a recognized virtual or problem adapter"
        }
        GraphicsRendererReason::NativeAutomatic => "Automatic found no compatibility signal",
    }
}

fn system_locate_schedule_guidance(
    status: &ottrin_search::SystemLocateScheduleStatus,
) -> &'static str {
    let detail = status.detail.as_deref().unwrap_or_default();
    if status.managed_by_ottrin {
        "Ottrin installed this system updatedb job for plocate fallback only; it does not update the SQLite index."
    } else if detail.contains("cron.weekly") {
        "Weekly system updates are fine for mostly stable system paths. Use a daily schedule only if you rely on plocate for frequently changing system-wide results."
    } else if detail.contains("cron.daily")
        || detail.contains("timer")
        || detail.contains("updatedb.timer")
    {
        "This is a good default for system path fallback. Ottrin's own SQLite index remains the main search source."
    } else {
        "Existing system maintenance detected. No extra setup is needed unless plocate results are stale."
    }
}

fn execute_system_locate_maintenance(
    platform: &DefaultPlatform,
    operation: SystemLocateMaintenance,
) -> (String, bool) {
    let request = PrivilegedRequest {
        command: PrivilegedCommand::SystemLocateMaintenance(operation),
        context: PrivilegedContext {
            reason: Some("Maintain the operating system filename database".to_string()),
            cwd: None,
        },
    };
    match platform.execute_privileged(&request) {
        Ok(response) => {
            let ok = response.status == PrivilegedStatus::Success;
            let message = response.message.unwrap_or_else(|| {
                if ok {
                    "System filename maintenance completed.".to_string()
                } else {
                    "System filename maintenance failed.".to_string()
                }
            });
            (message, ok)
        }
        Err(error) => (format!("Failed to run privileged helper: {error}"), false),
    }
}

