/// A selected storage root that disappeared from the latest discovery snapshot.
/// This is deliberately runtime-only: it preserves the user's in-memory tab
/// location without persisting a stale path as a new bookmark or redirecting it.
#[derive(Debug, Clone, PartialEq, Eq)]
struct UnavailableLocation {
    /// A stable identity is required for automatic reconnect. Mutable discovery
    /// keys (Linux device paths and Windows drive letters) intentionally leave
    /// this empty.
    stable_identity: Option<String>,
    root: PathBuf,
}

/// Volume and actual-path mount identity captured immediately before queueing.
/// Validation occurs again in the worker immediately before the platform call;
/// OS pathname mutation remains inherently racy after that final validation.
#[derive(Debug, Clone, PartialEq, Eq)]
struct StorageOperationBinding {
    root: PathBuf,
    stable_identity: Option<String>,
    kind: StorageOperationBindingKind,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum StorageOperationBindingKind {
    Discovered,
    /// The app's home root is deliberately treated as a narrow safe domain;
    /// it is not an interchangeable removable-volume mount point.
    #[cfg(not(target_os = "linux"))]
    Home,
    #[cfg(target_os = "linux")]
    Local {
        mount_id: u64,
        follow_symlink: bool,
    },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DeleteChoice {
    MoveToTrash,
    Cancel,
    DeletePermanently,
}

#[derive(Debug, Clone)]
struct DeletePostNav {
    tab_id: u64,
    dir: PathBuf,
    select_path: Option<PathBuf>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum OperationStatus {
    Queued,
    Stopped,
    Completed,
    Failed,
    NeedsReview,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum OperationRecoverability {
    Restorable,
    NotUndoable,
    BatchUndoUnavailable,
    SessionTracked,
    Informational,
}

#[derive(Debug, Clone)]
struct OperationRecord {
    id: u64,
    title: String,
    detail: String,
    status: OperationStatus,
    recoverability: OperationRecoverability,
    queued_at: Instant,
    finished_at: Option<Instant>,
    message: Option<String>,
    operation_paths: Vec<OperationPath>,
    path_move_undo: Option<PathMoveUndoState>,
    undo_kind: Option<PathMoveUndoKind>,
    path_move_undo_token: Option<PathMoveUndoToken>,
    retained_copy: Option<RetainedCopyOwnership>,
}

impl OperationRecord {
    fn timing_label(&self, now: Instant) -> String {
        if self
            .retained_copy
            .as_ref()
            .is_some_and(|owner| owner.restored)
        {
            return "Restored history · original time unavailable".to_owned();
        }
        let (label, end) = if self.status == OperationStatus::Queued {
            ("Elapsed", now)
        } else if let Some(finished) = self.finished_at {
            ("Duration", finished)
        } else {
            return "Duration unavailable".to_owned();
        };
        format!(
            "{label}: {}",
            format_duration_short(end.saturating_duration_since(self.queued_at))
        )
    }

    fn undo_kind(&self) -> PathMoveUndoKind {
        self.undo_kind.expect("Undo state has an operation kind")
    }

    fn can_clear_history(&self) -> bool {
        // Running work must still receive its result. Undo receipts also own
        // retained transaction data, including completed/failed Undo attempts.
        self.status != OperationStatus::Queued
            && self.path_move_undo_token.is_none()
            && self.retained_copy.is_none()
    }
}

#[derive(Debug, Clone)]
struct PathMoveUndoToken {
    receipt: OperationUndoReceipt,
    storage_bindings: Vec<StorageOperationBinding>,
    origin_tab_id: Option<u64>,
}

#[derive(Debug, Clone)]
struct TextEditUndoReceipt {
    session: Arc<TextEditSession>,
    original: String,
    path: PathBuf,
}

#[derive(Debug, Clone)]
enum CopyBatchUndoReceipt {
    // Completed session receipts retain their transaction ownership after a stop.
    Session {
        receipts: Vec<PathMoveUndoReceipt>,
        remaining: usize,
    },
    #[cfg(any(target_os = "linux", target_os = "windows"))]
    Retained(Box<ottrin_platform::RetainedCopyUndoPlan>),
}

impl CopyBatchUndoReceipt {
    fn remaining(&self) -> usize {
        match self {
            Self::Session { remaining, .. } => *remaining,
            #[cfg(any(target_os = "linux", target_os = "windows"))]
            Self::Retained(plan) => plan.remaining(),
        }
    }
    fn path_pairs(&self) -> Vec<(&Path, &Path)> {
        match self {
            Self::Session { receipts, .. } => receipts
                .iter()
                .flat_map(PathMoveUndoReceipt::path_pairs)
                .collect(),
            #[cfg(any(target_os = "linux", target_os = "windows"))]
            Self::Retained(plan) => plan.path_pairs(),
        }
    }
    fn undo_next(
        &mut self,
        platform: &dyn PlatformOps,
        progress: &mut dyn FnMut(u64) -> Result<(), PlatformError>,
    ) -> Result<(), PlatformError> {
        progress(0)?;
        match self {
            Self::Session {
                receipts,
                remaining,
            } => {
                platform.undo_copy_with_receipt(&receipts[*remaining - 1], progress)?;
                *remaining -= 1;
                Ok(())
            }
            #[cfg(target_os = "linux")]
            Self::Retained(plan) => plan.undo_next(),
            #[cfg(target_os = "windows")]
            Self::Retained(plan) => plan.undo_next_with_progress(progress),
        }
    }
}

#[derive(Debug, Clone)]
enum OperationUndoReceipt {
    PathMove(PathMoveUndoReceipt),
    #[cfg(target_os = "windows")]
    WindowsMove(ottrin_platform::WindowsMoveUndoPlan),
    CopyBatch(CopyBatchUndoReceipt),
    Chmod(ChmodUndoReceipt),
    Trash(TrashUndoReceipt),
    TextEdit(TextEditUndoReceipt),
}

impl OperationUndoReceipt {
    #[cfg(target_os = "windows")]
    fn path_move_receipt(&self) -> Option<&PathMoveUndoReceipt> {
        match self {
            Self::PathMove(receipt) => Some(receipt),
            Self::WindowsMove(plan) => Some(plan.receipt()),
            _ => None,
        }
    }
    fn path_pairs(&self) -> Vec<(&Path, &Path)> {
        match self {
            Self::CopyBatch(batch) => batch.path_pairs(),
            #[cfg(target_os = "windows")]
            Self::WindowsMove(plan) => plan.path_pairs(),
            Self::PathMove(receipt) => receipt.path_pairs(),
            _ => vec![(self.before_path(), self.after_path())],
        }
    }

    fn operation_paths(&self) -> Vec<OperationPath> {
        #[cfg(target_os = "windows")]
        if let Self::WindowsMove(plan) = self {
            return plan
                .paths()
                .iter()
                .cloned()
                .map(OperationPath::write)
                .collect();
        }
        self.path_pairs()
            .into_iter()
            .flat_map(|(before, after)| [before.to_path_buf(), after.to_path_buf()])
            .map(OperationPath::write)
            .collect()
    }

    fn before_path(&self) -> &Path {
        match self {
            Self::PathMove(receipt) => receipt.before_path(),
            #[cfg(target_os = "windows")]
            Self::WindowsMove(plan) => plan.before_path(),
            Self::CopyBatch(batch) => batch.path_pairs().first().expect("nonempty Copy batch").0,
            Self::Chmod(receipt) => receipt.path(),
            Self::Trash(receipt) => receipt.original_path(),
            Self::TextEdit(receipt) => &receipt.path,
        }
    }

    fn after_path(&self) -> &Path {
        match self {
            Self::PathMove(receipt) => receipt.after_path(),
            #[cfg(target_os = "windows")]
            Self::WindowsMove(plan) => plan.after_path(),
            Self::CopyBatch(batch) => batch.path_pairs().first().expect("nonempty Copy batch").1,
            Self::Chmod(receipt) => receipt.path(),
            Self::Trash(receipt) => receipt.trash_path(),
            Self::TextEdit(receipt) => &receipt.path,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PathMoveUndoKind {
    CreateFile,
    CreateFolder,
    Symlink,
    Chmod,
    Trash,
    TextEdit,
    Rename,
    Copy,
    Move,
}

fn path_move_undo_conflict_message(kind: PathMoveUndoKind) -> String {
    let operation = match kind {
        PathMoveUndoKind::CreateFile => "create file",
        PathMoveUndoKind::CreateFolder => "create folder",
        PathMoveUndoKind::Symlink => "symlink",
        PathMoveUndoKind::Chmod => "permission change",
        PathMoveUndoKind::Trash => "Trash move",
        PathMoveUndoKind::TextEdit => "text edit",
        PathMoveUndoKind::Rename => "rename",
        PathMoveUndoKind::Copy => "copy",
        PathMoveUndoKind::Move => "move",
    };
    format!(
        "Undo {operation} was not started because a conflicting file operation is still running."
    )
}

fn path_move_parent_directories(before: &Path, after: &Path) -> Vec<PathBuf> {
    let mut parents = before
        .parent()
        .map(Path::to_path_buf)
        .into_iter()
        .collect::<Vec<_>>();
    if let Some(after_parent) = after.parent()
        && !parents.iter().any(|parent| parent == after_parent)
    {
        parents.push(after_parent.to_path_buf());
    }
    parents
}

#[cfg(test)]
fn path_move_paths_overlap(
    first_before: &Path,
    first_after: &Path,
    second_before: &Path,
    second_after: &Path,
) -> bool {
    [first_before, first_after].into_iter().any(|first| {
        [second_before, second_after]
            .into_iter()
            .any(|second| first.starts_with(second) || second.starts_with(first))
    })
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum PathMoveUndoState {
    Available,
    UndoQueued,
    Undone,
    Unavailable { reason: String },
}

fn path_move_undo_action_is_available(
    status: OperationStatus,
    state: Option<&PathMoveUndoState>,
) -> bool {
    matches!(
        status,
        OperationStatus::Completed | OperationStatus::Stopped
    ) && matches!(state, Some(PathMoveUndoState::Available))
}

fn rename_selection_for_tab(
    origin_tab_id: Option<u64>,
    tab_id: u64,
    displays_parent: bool,
    selected_path: &Path,
) -> Option<PathBuf> {
    (origin_tab_id == Some(tab_id) && displays_parent).then(|| selected_path.to_path_buf())
}

/// Durable Move evidence discovered at startup.
/// A transaction id is kept as raw bytes, and pending-destination entries expose a
/// manual recovery action while recovery design is proven for that lifecycle.
#[cfg_attr(not(any(target_os = "windows", test)), allow(dead_code))]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RetainedMoveRecovery {
    // Retained evidence that cannot currently be admitted exposes no action.
    Unavailable,
    Forward,
    Undo,
    Undone,
}

impl RetainedMoveRecovery {
    fn action_label(self) -> Option<&'static str> {
        match self {
            Self::Forward => Some("Recover now"),
            Self::Undo => Some("Resume Undo"),
            Self::Unavailable | Self::Undone => None,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct RetainedMoveActivity {
    transaction_id: [u8; 16],
    phase: &'static str,
    recovery: RetainedMoveRecovery,
    #[cfg(any(target_os = "linux", target_os = "windows"))]
    plan: Option<NativeMoveRecoveryPlan>,
}

impl RetainedMoveActivity {
    fn transaction_id_hex(&self) -> String {
        self.transaction_id
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect()
    }
}

#[cfg(target_os = "linux")]
fn load_retained_move_activity() -> (Vec<RetainedMoveActivity>, Option<String>) {
    match discover_retained_move_transactions() {
        Ok(transactions) => {
            let mut admission_error = None;
            let activity = transactions
                .into_iter()
                .map(|transaction| {
                    let plan = if transaction.phase == JournalPhase::PendingDestination {
                        match NativeMoveRecoveryPlan::capture(transaction.transaction_id) {
                            Ok(plan) => Some(plan),
                            Err(error) => {
                                admission_error.get_or_insert_with(|| error.to_string());
                                None
                            }
                        }
                    } else {
                        None
                    };
                    RetainedMoveActivity {
                        transaction_id: transaction.transaction_id,
                        recovery: if plan.is_some() {
                            RetainedMoveRecovery::Forward
                        } else {
                            RetainedMoveRecovery::Unavailable
                        },
                        plan,
                        phase: match transaction.phase {
                            JournalPhase::Prepared => "prepared",
                            JournalPhase::ClaimIntent => "claim intent",
                            JournalPhase::Claimed => "claimed",
                            JournalPhase::UnexpectedClaimRetained => "unexpected claim retained",
                            JournalPhase::PendingDestination => "pending destination",
                            JournalPhase::Published => "published",
                            JournalPhase::CleanupPending => "cleanup pending",
                            JournalPhase::ClaimedSourceDeletionPending => {
                                "claimed source deletion pending"
                            }
                            JournalPhase::ClaimedSourceUnlinked => "claimed source unlinked",
                        },
                    }
                })
                .collect();
            (activity, admission_error)
        }
        Err(error) => (Vec::new(), Some(error.to_string())),
    }
}

#[cfg(any(target_os = "windows", test))]
fn windows_retained_move_activity(
    transaction: ottrin_platform::move_recovery::WindowsDiscoveredMoveTransaction,
) -> RetainedMoveActivity {
    RetainedMoveActivity {
        transaction_id: transaction.transaction_id,
        #[cfg(any(target_os = "linux", target_os = "windows"))]
        plan: None,
        phase: match transaction.undo_status {
            ottrin_platform::move_recovery::WindowsMoveUndoStatus::Pending => {
                match transaction.kind {
                    WindowsMoveTransactionKind::SameVolumeOverwrite => "Replace Undo pending",
                    WindowsMoveTransactionKind::CrossVolume => "Cross-volume Undo pending",
                }
            }
            ottrin_platform::move_recovery::WindowsMoveUndoStatus::Complete => {
                match transaction.kind {
                    WindowsMoveTransactionKind::SameVolumeOverwrite => "Replace undone",
                    WindowsMoveTransactionKind::CrossVolume => "Cross-volume Move undone",
                }
            }
            ottrin_platform::move_recovery::WindowsMoveUndoStatus::NotStarted => {
                match transaction.kind {
                    WindowsMoveTransactionKind::SameVolumeOverwrite => "same-volume overwrite",
                    WindowsMoveTransactionKind::CrossVolume => "cross-volume",
                }
            }
        },
        recovery: match transaction.undo_status {
            ottrin_platform::move_recovery::WindowsMoveUndoStatus::NotStarted => {
                RetainedMoveRecovery::Forward
            }
            ottrin_platform::move_recovery::WindowsMoveUndoStatus::Pending => {
                RetainedMoveRecovery::Undo
            }
            ottrin_platform::move_recovery::WindowsMoveUndoStatus::Complete => {
                RetainedMoveRecovery::Undone
            }
        },
    }
}

#[cfg(target_os = "windows")]
fn captured_windows_move_activity(
    mut transaction: ottrin_platform::move_recovery::WindowsDiscoveredMoveTransaction,
    plan: ottrin_platform::WindowsMoveRecoveryPlan,
) -> RetainedMoveActivity {
    transaction.undo_status = plan.undo_status();
    let mut activity = windows_retained_move_activity(transaction);
    activity.plan = Some(plan);
    activity
}

#[cfg(target_os = "windows")]
fn load_retained_move_activity() -> (Vec<RetainedMoveActivity>, Option<String>) {
    match discover_retained_move_transactions() {
        Ok(transactions) => {
            let mut error = None;
            let activity = transactions
                .into_iter()
                .map(|transaction| {
                    match ottrin_platform::WindowsMoveRecoveryPlan::capture(
                        transaction.transaction_id,
                    ) {
                        Ok(plan) => captured_windows_move_activity(transaction, plan),
                        Err(reason) => {
                            let mut activity = windows_retained_move_activity(transaction);
                            activity.recovery = RetainedMoveRecovery::Unavailable;
                            error.get_or_insert_with(|| reason.to_string());
                            activity
                        }
                    }
                })
                .collect();
            (activity, error)
        }
        Err(error) => (Vec::new(), Some(error.to_string())),
    }
}

#[cfg(not(any(target_os = "linux", target_os = "windows")))]
fn load_retained_move_activity() -> (Vec<RetainedMoveActivity>, Option<String>) {
    (Vec::new(), None)
}

#[cfg(target_os = "windows")]
#[derive(Debug, Clone)]
enum CopyRecoveryAction {
    Forward(ottrin_platform::RetainedCopyResumePlan),
    Abort(ottrin_platform::RetainedCopyAbortPlan),
    NameRelease(ottrin_platform::RetainedCopyNameReleasePlan),
    NameReleaseBlocked,
}
#[cfg(target_os = "windows")]
impl CopyRecoveryAction {
    fn transaction_id(&self) -> Option<&str> {
        match self {
            Self::Forward(plan) => Some(plan.transaction_id()),
            Self::Abort(plan) => Some(plan.transaction_id()),
            Self::NameRelease(plan) => Some(plan.transaction_id()),
            Self::NameReleaseBlocked => None,
        }
    }
    fn complete(&self) -> bool {
        match self {
            Self::Forward(plan) => plan.complete(),
            Self::Abort(plan) => plan.complete(),
            Self::NameRelease(plan) => plan.complete(),
            Self::NameReleaseBlocked => true,
        }
    }
    fn is_name_release(&self) -> bool {
        matches!(self, Self::NameRelease(_) | Self::NameReleaseBlocked)
    }
    fn path_pairs(&self) -> Vec<(&Path, &Path)> {
        match self {
            Self::Forward(plan) => plan.path_pairs(),
            Self::Abort(plan) => vec![(plan.destination(), plan.destination())],
            Self::NameRelease(plan) => vec![(plan.destination(), plan.destination())],
            Self::NameReleaseBlocked => Vec::new(),
        }
    }
    fn observed_location(&self) -> Option<&Path> {
        match self {
            Self::Forward(plan) => Some(plan.observed_location()),
            _ => None,
        }
    }
    fn label(&self) -> &'static str {
        if matches!(self, Self::Abort(_)) {
            "End copy attempt…"
        } else if self.is_name_release() {
            "Finish releasing name"
        } else {
            "Resume copy"
        }
    }
    fn released_phase(&self) -> Option<ottrin_platform::WindowsCopyPhase> {
        match self {
            Self::NameRelease(plan) => Some(plan.admitted_phase()),
            Self::Abort(_) => Some(ottrin_platform::WindowsCopyPhase::Aborted),
            _ => None,
        }
    }
    fn success_message(&self) -> &'static str {
        if matches!(self, Self::Abort(_)) {
            "Copy attempt ended. Partial files and recovery records are preserved."
        } else if self.is_name_release() {
            "File name released. Retained files are unchanged."
        } else {
            "Copy recovery completed."
        }
    }
    fn run(
        &mut self,
        progress: impl FnMut(u64) -> Result<(), PlatformError>,
    ) -> Result<(), PlatformError> {
        match self {
            Self::Forward(plan) => plan.resume(progress),
            Self::Abort(plan) => plan.end_attempt(progress),
            Self::NameRelease(plan) => plan.finish(progress),
            Self::NameReleaseBlocked => Err(PlatformError::Io(
                "Copy recovery has no admitted action; refresh status.".into(),
            )),
        }
    }
}

#[derive(Debug, Clone)]
struct RetainedCopyOwnership {
    key: String,
    transactions: Vec<String>,
    blocked_by: Vec<String>,
    restored: bool,
    finalization: Option<String>,
    #[cfg(target_os = "windows")]
    recovery: Option<CopyRecoveryAction>,
    #[cfg(target_os = "windows")]
    cleanup_phase: Option<ottrin_platform::WindowsCopyPhase>,
    #[cfg(target_os = "windows")]
    recovery_location: Option<PathBuf>,
}

#[derive(Debug, Clone)]
struct RestoredCopyActivity {
    ownership: RetainedCopyOwnership,
    detail: String,
    undo: PathMoveUndoState,
    receipt: Option<CopyBatchUndoReceipt>,
}

impl RestoredCopyActivity {
    fn title(&self) -> &'static str {
        if self.ownership.transactions.is_empty() {
            "Copy recovery record needs review"
        } else {
            "Copy from previous session"
        }
    }
}

type RetainedCopySnapshot = (Vec<RestoredCopyActivity>, Option<String>);

#[cfg(target_os = "linux")]
fn load_retained_copy_activity() -> RetainedCopySnapshot {
    let result = (|| -> Result<Vec<RestoredCopyActivity>, PlatformError> {
        let finalizations = ottrin_platform::discover_retained_copy_finalizations()?;
        let finalized_ids = finalizations
            .iter()
            .flat_map(|plan| plan.transaction_ids().into_iter().map(str::to_owned))
            .collect::<HashSet<_>>();
        let entries = ottrin_platform::discover_retained_copy_transactions()?
            .into_iter()
            .filter(|entry| !finalized_ids.contains(&entry.transaction_id))
            .collect();
        let mut activity = group_retained_copy_activity(entries);
        for plan in finalizations {
            activity.push(RestoredCopyActivity {
                ownership: RetainedCopyOwnership {
                    key: format!("cleanup:{}", plan.id()),
                    transactions: plan.transaction_ids().into_iter().map(str::to_owned).collect(),
                    blocked_by: Vec::new(), restored: true, finalization: Some(plan.id().into()),
                },
                detail: "Interrupted Copy cleanup · retained recovery bookkeeping remains".into(),
                undo: PathMoveUndoState::Unavailable { reason: "Copy cleanup has revoked Undo. Finish cleanup to release its remaining bookkeeping.".into() },
                receipt: None,
            });
        }
        Ok(activity)
    })();
    match result {
        Ok(activity) => (activity, None),
        Err(error) => (Vec::new(), Some(error.to_string())),
    }
}

#[cfg(target_os = "windows")]
fn load_retained_copy_activity() -> RetainedCopySnapshot {
    match ottrin_platform::discover_retained_copy_transactions() {
        Ok(entries) => (
            entries
                .into_iter()
                .map(|entry| {
                    let admission = entry
                        .transaction_id
                        .as_deref()
                        .filter(|_| windows_copy_can_admit(&entry))
                        .map(ottrin_platform::restore_retained_copy_undo_plan);
                    let recovery = entry.transaction_id.as_deref().and_then(|id| {
                        if entry.evidence
                            == ottrin_platform::WindowsCopyRecoveryEvidence::PendingNameRelease
                        {
                            Some(
                                ottrin_platform::restore_retained_copy_name_release_plan(id)
                                    .map(CopyRecoveryAction::NameRelease),
                            )
                        } else if windows_copy_can_resume(&entry) {
                            Some(
                                ottrin_platform::restore_retained_copy_resume_plan(id)
                                    .map(CopyRecoveryAction::Forward),
                            )
                        } else if windows_copy_can_abort(&entry) {
                            Some(
                                ottrin_platform::restore_retained_copy_abort_plan(id)
                                    .map(CopyRecoveryAction::Abort),
                            )
                        } else {
                            None
                        }
                    });
                    windows_retained_copy_activity(entry, admission, recovery)
                })
                .collect(),
            None,
        ),
        Err(error) => (Vec::new(), Some(error.to_string())),
    }
}

#[cfg(target_os = "windows")]
fn windows_copy_can_admit(entry: &ottrin_platform::WindowsRetainedCopyStatus) -> bool {
    if entry.transaction_id.is_none() {
        return false;
    }
    use ottrin_platform::{WindowsCopyPhase as Phase, WindowsCopyRecoveryEvidence as Evidence};
    match entry.evidence {
        Evidence::VerifiedTree => {
            matches!(entry.phase, Some(Phase::Completed | Phase::UndoPending))
        }
        Evidence::VerifiedOriginal => entry.phase == Some(Phase::UndoPending),
        _ => false,
    }
}

#[cfg(target_os = "windows")]
fn windows_copy_can_resume(entry: &ottrin_platform::WindowsRetainedCopyStatus) -> bool {
    use ottrin_platform::{WindowsCopyPhase as Phase, WindowsCopyRecoveryEvidence as Evidence};
    entry.transaction_id.is_some()
        && entry.evidence == Evidence::VerifiedTree
        && matches!(
            entry.phase,
            Some(
                Phase::Staged
                    | Phase::PlanningPermissions
                    | Phase::ReadyToPublish
                    | Phase::RetainingOriginal
                    | Phase::PublicationPending
                    | Phase::ApplyingPermissions
                    | Phase::Finalizing
            )
        )
}

#[cfg(target_os = "windows")]
fn windows_copy_can_abort(entry: &ottrin_platform::WindowsRetainedCopyStatus) -> bool {
    use ottrin_platform::{WindowsCopyPhase as Phase, WindowsCopyRecoveryEvidence as Evidence};
    entry.transaction_id.is_some()
        && entry.phase == Some(Phase::Staging)
        && matches!(
            entry.evidence,
            Evidence::UnverifiedStage | Evidence::NeedsReview { .. }
        )
}

#[cfg(target_os = "windows")]
fn windows_retained_copy_activity(
    entry: ottrin_platform::WindowsRetainedCopyStatus,
    admission: Option<Result<ottrin_platform::RetainedCopyUndoPlan, PlatformError>>,
    recovery_admission: Option<Result<CopyRecoveryAction, PlatformError>>,
) -> RestoredCopyActivity {
    use ottrin_platform::{WindowsCopyPhase as Phase, WindowsCopyRecoveryEvidence as Evidence};
    let recovery_location = entry.transaction.clone();
    let eligible = windows_copy_can_admit(&entry);
    let resumable = windows_copy_can_resume(&entry);
    let abortable = windows_copy_can_abort(&entry);
    let releasing = entry.evidence == Evidence::PendingNameRelease;
    let mut phase = match entry.phase {
        Some(Phase::Staging) => "Staging interrupted",
        Some(Phase::Aborted) => "Copy attempt ended · partial files kept",
        Some(Phase::Staged) => "Staged copy",
        Some(Phase::PlanningPermissions) => "Permission planning interrupted",
        Some(Phase::ReadyToPublish) => "Prepared copy",
        Some(Phase::RetainingOriginal) => "Original retention interrupted",
        Some(Phase::PublicationPending) => "Publication interrupted",
        Some(Phase::ApplyingPermissions) => "Permission application interrupted",
        Some(Phase::Finalizing) => "Final verification interrupted",
        Some(Phase::Completed) => "Completed copy",
        Some(Phase::UndoPending) => "Undo interrupted",
        Some(Phase::Undone) => "Copy undone · retained data",
        Some(Phase::CleaningUp) => "Cleanup interrupted",
        None => "Copy journal needs review",
    };
    let (evidence, mut undo) = match entry.evidence {
        Evidence::VerifiedTree if entry.phase == Some(Phase::Undone) => {
            ("Retained data verified", PathMoveUndoState::Undone)
        }
        Evidence::VerifiedOriginal if entry.phase == Some(Phase::Undone) => {
            ("Original restored · replacement withdrawn", PathMoveUndoState::Undone)
        }
        Evidence::VerifiedOriginal => (
            "Original verified · replacement already withdrawn",
            PathMoveUndoState::Unavailable {
                reason: "Original restoration requires a freshly admitted Undo receipt. Restoration does not change retained replacement data.".into(),
            },
        ),
        Evidence::VerifiedTree => (
            "Current data verified",
            PathMoveUndoState::Unavailable {
                reason: "This copy has no freshly admitted Undo receipt. Retained data is preserved; verification alone does not authorize Undo or cleanup.".into(),
            },
        ),
        Evidence::PendingNameRelease => (
            "File name release pending · retained files kept",
            PathMoveUndoState::Unavailable {
                reason: "The file name reservation needs recovery. It can be released without changing or deleting retained files.".into(),
            },
        ),
        Evidence::VerifiedCleanup => (
            "Remaining cleanup data verified",
            PathMoveUndoState::Unavailable {
                reason: "Cleanup has started. Undo and forward recovery are unavailable; remaining data is preserved until cleanup is explicitly resumed.".into(),
            },
        ),
        Evidence::UnverifiedStage if entry.phase == Some(Phase::Aborted) => (
            "Payload remains unverified",
            PathMoveUndoState::Unavailable {
                reason: "This copy attempt has ended. Its partial files and recovery records are preserved; it cannot resume or publish.".into(),
            },
        ),
        Evidence::UnverifiedStage => (
            "Staging incomplete · payload not verified",
            PathMoveUndoState::Unavailable {
                reason: "Copying stopped before all file contents were verified. Resume and automatic cleanup are unavailable. Retained files and recovery records have been kept.".into(),
            },
        ),
        Evidence::NeedsReview { reason } => (
            "Current data needs review",
            PathMoveUndoState::Unavailable { reason },
        ),
    };
    let mut location = entry.owned_location;
    let mut receipt = None;
    if eligible {
        match admission {
            Some(Ok(plan))
                if entry
                    .transaction_id
                    .as_deref()
                    .is_some_and(|id| plan.transaction_ids() == vec![id]) =>
            {
                phase = match plan.admitted_phase() {
                    Phase::UndoPending => "Undo interrupted · ready to resume",
                    _ => "Completed copy · ready to undo",
                };
                location = Some(plan.observed_location().to_path_buf());
                undo = PathMoveUndoState::Available;
                receipt = Some(CopyBatchUndoReceipt::Retained(Box::new(plan)));
            }
            Some(Err(error)) => {
                undo = PathMoveUndoState::Unavailable {
                    reason: error.to_string(),
                }
            }
            Some(Ok(_)) => {
                undo = PathMoveUndoState::Unavailable {
                    reason: "Copy transaction changed during admission; refresh its status".into(),
                }
            }
            None => {}
        }
    }
    let mut recovery = releasing.then_some(CopyRecoveryAction::NameReleaseBlocked);
    if releasing {
        phase = "File name release pending";
    }
    if resumable || releasing || abortable {
        match recovery_admission {
            Some(Ok(plan))
                if plan.transaction_id() == entry.transaction_id.as_deref()
                    && plan.is_name_release() == releasing
                    && matches!(plan, CopyRecoveryAction::Abort(_)) == abortable =>
            {
                phase = if releasing {
                    "Ready to release file name"
                } else if abortable {
                    "Incomplete copy · can end attempt and keep files"
                } else {
                    "Verified copy · ready to resume"
                };
                if let Some(observed) = plan.observed_location() {
                    location = Some(observed.to_path_buf());
                }
                recovery = Some(plan);
            }
            Some(Err(error)) => {
                undo = PathMoveUndoState::Unavailable {
                    reason: error.to_string(),
                }
            }
            Some(Ok(_)) => {
                undo = PathMoveUndoState::Unavailable {
                    reason: "Copy transaction changed during admission; refresh its status".into(),
                }
            }
            None => {}
        }
    }
    let key = if let Some(id) = &entry.transaction_id {
        format!("transaction:{id}")
    } else {
        use std::os::windows::ffi::OsStrExt;
        // Internal row identity must preserve raw native names; do not turn a
        // display label or a lossy filename into a transaction ID.
        let native_key = entry
            .transaction
            .as_ref()
            .into_iter()
            .flat_map(|path| path.as_os_str().encode_wide())
            .map(|unit| format!("{unit:04x}"))
            .collect::<String>();
        format!("unrecognized-copy-record:{native_key}")
    };
    let mut detail = format!("{phase} · {evidence}");
    if let Some(location) = location {
        detail.push_str(&format!(" · Data: {}", path_label(&location)));
    }
    if let Some(id) = &entry.transaction_id {
        detail.push_str(&format!(" · Transaction: {id}"));
    }
    RestoredCopyActivity {
        ownership: RetainedCopyOwnership {
            key,
            transactions: entry.transaction_id.into_iter().collect(),
            blocked_by: Vec::new(),
            restored: true,
            finalization: None,
            cleanup_phase: entry.phase,
            #[cfg(target_os = "windows")]
            recovery_location,
            recovery,
        },
        detail,
        undo,
        receipt,
    }
}

#[cfg(all(not(any(target_os = "linux", target_os = "windows")), not(test)))]
fn load_retained_copy_activity() -> RetainedCopySnapshot {
    (Vec::new(), None)
}

#[cfg(target_os = "linux")]
fn group_retained_copy_activity(
    entries: Vec<ottrin_platform::RetainedCopyStatus>,
) -> Vec<RestoredCopyActivity> {
    use ottrin_platform::CopyRecoveryEvidence;
    let mut groups = std::collections::BTreeMap::<String, Vec<_>>::new();
    for entry in entries {
        let key = entry
            .operation
            .as_ref()
            .map(|operation| format!("operation:{}", operation.id))
            .unwrap_or_else(|| format!("transaction:{}", entry.transaction_id));
        groups.entry(key).or_default().push(entry);
    }
    groups.into_iter().map(|(key, mut entries)| {
        entries.sort_by_key(|entry| entry.operation.as_ref().map(|operation| operation.item_index));
        let expected = entries[0].operation.as_ref().map(|operation| operation.item_count);
        let mut positions = HashSet::new();
        let mut reason = None;
        let mut blocked_by = Vec::new();
        let mut undone = 0;
        for entry in &entries {
            match &entry.operation {
                Some(operation) if Some(operation.item_count) == expected
                    && positions.insert(operation.item_index) => {},
                _ => { reason = Some("Copy operation metadata is missing, duplicated or inconsistent".to_owned()); },
            }
            match &entry.evidence {
                CopyRecoveryEvidence::UndoneRetainedObjectsAndContentsMatch => undone += 1,
                CopyRecoveryEvidence::PublishedObjectsAndContentsMatch
                | CopyRecoveryEvidence::UndoReadyToWithdraw
                | CopyRecoveryEvidence::UndoWithdrawalMatches => {
                },
                CopyRecoveryEvidence::PublicationRetainedByCopy { transaction_id } => {
                    blocked_by.push(transaction_id.clone());
                    if !entries.iter().any(|owner| &owner.transaction_id == transaction_id) {
                    reason = Some(format!("Undo the newer copy of {} first. Ottrin retains this version until that copy is undone.", path_label(entry.publication.as_ref().expect("validated Copy publication"))));
                    }
                },
                CopyRecoveryEvidence::NeedsReview { reason: error } => reason = Some(error.clone()),
                CopyRecoveryEvidence::MatchingJournals => reason = Some("Copy publication was interrupted and needs reconciliation".into()),
                CopyRecoveryEvidence::CleanupReady => reason = Some("Cleanup-only evidence cannot restore Undo".into()),
                CopyRecoveryEvidence::CleanupPending => reason = Some("Copy cleanup is in progress; Undo is no longer available".into()),
                CopyRecoveryEvidence::CleanupComplete => reason = Some("Retained Copy data was reclaimed; history finalization is pending".into()),
            }
        }
        let detail = match expected {
            Some(count) if count == entries.len() => format!("Restored Copy · {} retained item{} · {undone} already undone", entries.len(), plural_s(entries.len())),
            Some(count) => format!("Restored Copy · {} retained of {count} requested · {undone} already undone · other item outcomes unknown", entries.len()),
            None => "Retained Copy needs review".into(),
        };
        let receipt = if reason.is_none() && undone < entries.len() {
            match ottrin_platform::restore_retained_copy_undo_plan(&entries) {
                Ok(plan) if plan.transaction_ids() == entries.iter()
                    .filter(|entry| entry.phase != Some(ottrin_platform::CopyPhase::Undone))
                    .map(|entry| entry.transaction_id.as_str()).collect::<Vec<_>>() => Some(CopyBatchUndoReceipt::Retained(Box::new(plan))),
                Ok(_) => { reason = Some("Copy batch changed during Activity restoration; refresh its status".into()); None },
                Err(error) => { reason = Some(error.to_string()); None },
            }
        } else { None };
        let undo = if let Some(reason) = reason {
            PathMoveUndoState::Unavailable { reason }
        } else if receipt.is_none() {
            PathMoveUndoState::Undone
        } else {
            PathMoveUndoState::Available
        };
        RestoredCopyActivity {
            ownership: RetainedCopyOwnership { key, transactions: entries.into_iter().map(|entry| entry.transaction_id).collect(), blocked_by, restored: true, finalization: None },
            detail,
            undo,
            receipt,
        }
    }).collect()
}

fn restored_copy_status(undo: &PathMoveUndoState) -> OperationStatus {
    if matches!(undo, PathMoveUndoState::Unavailable { .. }) {
        OperationStatus::NeedsReview
    } else {
        OperationStatus::Completed
    }
}

fn restored_copy_token(receipt: Option<CopyBatchUndoReceipt>) -> Option<PathMoveUndoToken> {
    Some(PathMoveUndoToken {
        storage_bindings: Vec::new(),
        origin_tab_id: None,
        receipt: OperationUndoReceipt::CopyBatch(receipt?),
    })
}

fn copy_receipt_transaction_ids(record: &OperationRecord) -> Vec<String> {
    let Some(token) = &record.path_move_undo_token else {
        return Vec::new();
    };
    if record.undo_kind != Some(PathMoveUndoKind::Copy) {
        return Vec::new();
    }
    #[cfg(any(target_os = "linux", target_os = "windows"))]
    if let OperationUndoReceipt::CopyBatch(CopyBatchUndoReceipt::Retained(plan)) = &token.receipt {
        return plan
            .transaction_ids()
            .into_iter()
            .map(str::to_owned)
            .collect();
    }
    match &token.receipt {
        OperationUndoReceipt::PathMove(receipt) => receipt
            .copy_transaction_id()
            .map(str::to_owned)
            .into_iter()
            .collect(),
        OperationUndoReceipt::CopyBatch(CopyBatchUndoReceipt::Session { receipts, .. }) => receipts
            .iter()
            .filter_map(|receipt| receipt.copy_transaction_id().map(str::to_owned))
            .collect(),
        _ => Vec::new(),
    }
}

type RetainedMoveSnapshot = (Vec<RetainedMoveActivity>, Option<String>);
#[cfg(target_os = "windows")]
type MoveCleanupPreparation = (
    [u8; 16],
    RetainedActivityLoader<Result<Option<ottrin_platform::WindowsMoveRecoveryPlan>, String>>,
);

/// One background scan at a time. A refresh during a scan invalidates its result
/// and requests one replacement scan, regardless of how many refreshes arrive.
struct RetainedActivityLoader<T> {
    request_tx: mpsc::SyncSender<()>,
    result_rx: Receiver<T>,
    pending: bool,
    refresh_again: bool,
}

impl<T: Send + 'static> RetainedActivityLoader<T> {
    fn spawn_with(mut load: impl FnMut() -> T + Send + 'static) -> Self {
        let (request_tx, request_rx) = mpsc::sync_channel(1);
        let (result_tx, result_rx) = mpsc::sync_channel(1);
        std::thread::spawn(move || {
            while request_rx.recv().is_ok() {
                if result_tx.send(load()).is_err() {
                    break;
                }
            }
        });
        Self {
            request_tx,
            result_rx,
            pending: false,
            refresh_again: false,
        }
    }

    fn request(&mut self) -> Result<(), &'static str> {
        if self.pending {
            self.refresh_again = true;
            return Ok(());
        }
        self.request_tx
            .try_send(())
            .map_err(|_| "Retained Activity worker is unavailable")?;
        self.pending = true;
        Ok(())
    }

    fn poll(&mut self) -> Option<Result<T, &'static str>> {
        if !self.pending {
            return None;
        }
        let result = match self.result_rx.try_recv() {
            Ok(result) => result,
            Err(mpsc::TryRecvError::Empty) => return None,
            Err(mpsc::TryRecvError::Disconnected) => {
                self.pending = false;
                self.refresh_again = false;
                return Some(Err("Retained Activity worker stopped"));
            }
        };
        self.pending = false;
        if std::mem::take(&mut self.refresh_again) {
            // Never expose evidence from a scan superseded by an operation.
            return self.request().err().map(Err);
        }
        Some(Ok(result))
    }
}

