/// A UI request is distinct from the immutable cache entry it expects. A file
/// can change A -> B -> A while earlier workers are still running, so cache
/// identity alone cannot say which response is newest for the visible slot.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum PreviewRequestTarget {
    Thumbnail,
    Original,
    ZoomedOriginal,
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
struct PreviewRequestSlot {
    path: PathBuf,
    target: PreviewRequestTarget,
    target_dim: u32,
    page_index: usize,
}

impl PreviewRequestSlot {
    fn new(
        path: PathBuf,
        target: PreviewRequestTarget,
        target_dim: u32,
        page_index: usize,
    ) -> Self {
        Self {
            path,
            target,
            target_dim,
            page_index,
        }
    }
}

#[derive(Debug, Clone)]
struct PreviewRequestState {
    request_id: u64,
    cache_key: String,
    cancellation: Arc<AtomicBool>,
}

#[derive(Debug, Default)]
struct PreviewRequestScheduler {
    current: HashMap<PreviewRequestSlot, PreviewRequestState>,
    inflight: HashSet<PreviewRequestSlot>,
    next_request_id: u64,
}

impl PreviewRequestScheduler {
    /// Reserves a new request only when this slot expects different content.
    /// A returning key must supersede an older request after an intervening
    /// generation, even if that older request used the same cache key.
    fn reserve(&mut self, slot: PreviewRequestSlot, cache_key: String) -> Option<u64> {
        if self
            .current
            .get(&slot)
            .is_some_and(|state| state.cache_key == cache_key)
        {
            return None;
        }
        self.next_request_id = self.next_request_id.wrapping_add(1).max(1);
        let request_id = self.next_request_id;
        if let Some(previous) = self.current.remove(&slot) {
            previous.cancellation.store(true, Ordering::Release);
        }
        let cancellation = Arc::new(AtomicBool::new(false));
        self.current.insert(
            slot.clone(),
            PreviewRequestState {
                request_id,
                cache_key,
                cancellation,
            },
        );
        self.inflight.insert(slot);
        Some(request_id)
    }

    fn cancel(&mut self, slot: &PreviewRequestSlot, request_id: u64) {
        if self
            .current
            .get(slot)
            .is_some_and(|state| state.request_id == request_id)
        {
            if let Some(state) = self.current.remove(slot) {
                state.cancellation.store(true, Ordering::Release);
            }
            self.inflight.remove(slot);
        }
    }

    fn cancellation(&self, slot: &PreviewRequestSlot, request_id: u64) -> Option<Arc<AtomicBool>> {
        self.current
            .get(slot)
            .filter(|state| state.request_id == request_id)
            .map(|state| Arc::clone(&state.cancellation))
    }

    fn is_inflight_for(&self, path: &Path, page_index: usize) -> bool {
        self.inflight
            .iter()
            .any(|slot| slot.path == path && slot.page_index == page_index)
    }

    fn accept_response(
        &mut self,
        slot: &PreviewRequestSlot,
        request_id: u64,
        cache_key: &str,
    ) -> bool {
        let current = self.current.get(slot);
        let accepted = current
            .is_some_and(|state| state.request_id == request_id && state.cache_key == cache_key);
        if accepted {
            self.current.remove(slot);
            self.inflight.remove(slot);
        }
        accepted
    }

    #[cfg(test)]
    fn is_inflight(&self, slot: &PreviewRequestSlot) -> bool {
        self.inflight.contains(slot)
    }
}

#[derive(Debug, Clone, Copy)]
struct VisualPreviewRenderSpec {
    max_size: Vec2,
    corner_radius: u8,
    page_index: usize,
    fit: bool,
    fit_width: bool,
    zoom: f32,
}

impl VisualPreviewRenderSpec {
    fn fit_bounds(self) -> Vec2 {
        if self.fit_width {
            Vec2::new(self.max_size.x, f32::INFINITY)
        } else {
            self.max_size
        }
    }
}

/// Render the one sizing control strip shared by Preview and Quick Inspector.
/// A manual zoom deliberately survives later viewport changes; only a fit mode
/// derives a size from the current available bounds.
fn render_visual_sizing_controls(
    ui: &mut egui::Ui,
    _kind: PreviewKind,
    visual_fit: &mut bool,
    visual_fit_width: &mut bool,
    visual_zoom: &mut f32,
    c: Colors,
) {
    let fit_label = if *visual_fit_width {
        "Fit width"
    } else {
        "Fit page"
    };
    ui.vertical(|ui| {
        ui.horizontal_wrapped(|ui| {
            if ui
                .add(egui::Button::new("Fit page").small().themed(&c))
                .on_hover_text("Show the complete page or image in the viewport.")
                .clicked()
            {
                *visual_fit = true;
                *visual_fit_width = false;
            }
            if ui
                .add(egui::Button::new("Fit width").small().themed(&c))
                .on_hover_text("Match the preview width and scroll vertically.")
                .clicked()
            {
                *visual_fit = true;
                *visual_fit_width = true;
            }
            if ui
                .add(egui::Button::new("100%").small().themed(&c))
                .on_hover_text("Show the page or image at its natural size and scroll.")
                .clicked()
            {
                *visual_fit = false;
                *visual_zoom = 1.0;
            }
        });
        ui.horizontal_wrapped(|ui| {
            if ui
                .add(egui::Button::new("−").small().themed(&c))
                .on_hover_text("Zoom out")
                .clicked()
            {
                *visual_fit = false;
                *visual_zoom = (*visual_zoom / 1.2).clamp(0.1, 8.0);
            }
            ui.add(
                egui::Label::new(
                    RichText::new(if *visual_fit {
                        format!("{fit_label} · {}%", (*visual_zoom * 100.0).round() as u32)
                    } else {
                        format!("{}%", (*visual_zoom * 100.0).round() as u32)
                    })
                    .color(c.text_dim)
                    .size(10.5 * c.font_scale),
                )
                .wrap_mode(egui::TextWrapMode::Extend),
            );
            if ui
                .add(egui::Button::new("+").small().themed(&c))
                .on_hover_text("Zoom in")
                .clicked()
            {
                *visual_fit = false;
                *visual_zoom = (*visual_zoom * 1.2).clamp(0.1, 8.0);
            }
        });
    });
}

fn submit_sized_preview(
    ui: &mut egui::Ui,
    image: egui::Image<'static>,
    fit: bool,
    zoom: &mut f32,
) -> egui::Response {
    let source = image
        .load_for_size(ui.ctx(), ui.available_size())
        .ok()
        .and_then(|poll| poll.size());
    let response = ui.add(image);
    if fit
        && let Some(source) = source
        && source.x > 0.0
    {
        let effective = response.rect.width() / source.x;
        if (*zoom - effective).abs() > 0.0001 {
            *zoom = effective;
            ui.ctx().request_repaint();
        }
    }
    response
}

fn width_fit_size(source_size: Vec2, bounds: Vec2) -> Option<Vec2> {
    (bounds.y.is_infinite() && source_size.x > 0.0).then(|| {
        let fitted = preview_render::fit_size(
            source_size,
            bounds,
            preview_render::PreviewSizingMode::FitWidth,
        );
        Vec2::new(bounds.x, fitted.y)
    })
}

fn preview_image_with_fit_bounds(
    uri: String,
    bytes: Vec<u8>,
    bounds: Vec2,
    corner_radius: u8,
) -> egui::Image<'static> {
    let size = image::load_from_memory(&bytes).ok().map(|decoded| {
        let source = Vec2::new(decoded.width() as f32, decoded.height() as f32);
        width_fit_size(source, bounds).unwrap_or_else(|| {
            preview_render::fit_size(source, bounds, preview_render::PreviewSizingMode::FitPage)
        })
    });
    let image = egui::Image::from_bytes(uri, bytes).corner_radius(corner_radius);
    if let Some(size) = size {
        image.fit_to_exact_size(size)
    } else {
        image.max_width(bounds.x).max_height(bounds.y)
    }
}

#[derive(Debug, Default)]
struct PreviewLoadSlot {
    generation: u64,
    desired: Option<(PathBuf, EntryKind)>,
    inflight: Option<u64>,
    completed: Option<u64>,
    cancellation: Option<Arc<AtomicBool>>,
}

impl PreviewLoadSlot {
    fn select(&mut self, path: PathBuf, kind: EntryKind) -> u64 {
        if self.desired.as_ref() != Some(&(path.clone(), kind)) {
            if let Some(cancellation) = self.cancellation.take() {
                cancellation.store(true, Ordering::Relaxed);
            }
            self.generation = self.generation.wrapping_add(1).max(1);
            self.desired = Some((path, kind));
            self.inflight = None;
            self.completed = None;
            self.cancellation = Some(Arc::new(AtomicBool::new(false)));
        }
        self.generation
    }

    fn mark_enqueued(&mut self, generation: u64) {
        if generation == self.generation {
            self.inflight = Some(generation);
        }
    }

    fn invalidate(&mut self) {
        if let Some(cancellation) = self.cancellation.take() {
            cancellation.store(true, Ordering::Relaxed);
        }
        self.generation = self.generation.wrapping_add(1).max(1);
        self.desired = None;
        self.inflight = None;
        self.completed = None;
    }

    fn mark_response(&mut self, generation: u64, accepted: bool) {
        if self.inflight == Some(generation) {
            self.inflight = None;
        }
        if accepted && generation == self.generation {
            self.completed = Some(generation);
        }
    }

    fn next_request(&self) -> Option<u64> {
        (self.desired.is_some()
            && self.inflight != Some(self.generation)
            && self.completed != Some(self.generation))
        .then_some(self.generation)
    }

    fn cancellation(&self, generation: u64) -> Option<Arc<AtomicBool>> {
        if generation == self.generation {
            self.cancellation.as_ref().map(Arc::clone)
        } else {
            None
        }
    }

    fn is_pending(&self) -> bool {
        self.desired.is_some() && self.completed != Some(self.generation)
    }

    fn accepts(&self, generation: u64, path: &Path) -> bool {
        generation == self.generation
            && self
                .desired
                .as_ref()
                .is_some_and(|(desired, _)| desired == path)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PreviewTarget {
    Overlay,
    InfoPanel,
    SearchResult,
}

impl PreviewTarget {
    fn index(self) -> usize {
        match self {
            Self::Overlay => 0,
            Self::InfoPanel => 1,
            Self::SearchResult => 2,
        }
    }
}

#[derive(Debug)]
struct PreviewLoadRequest {
    target: PreviewTarget,
    generation: u64,
    request: PreviewRequest,
    cancellation: Arc<AtomicBool>,
}

#[derive(Debug)]
struct PreviewLoadResponse {
    target: PreviewTarget,
    generation: u64,
    path: PathBuf,
    data: PreviewData,
}

fn spawn_preview_loader_with<F>(
    loader: F,
) -> (
    mpsc::SyncSender<PreviewLoadRequest>,
    Receiver<PreviewLoadResponse>,
)
where
    F: Fn(&PreviewRequest, &AtomicBool) -> PreviewData + Send + 'static,
{
    let (request_tx, request_rx) = mpsc::sync_channel::<PreviewLoadRequest>(1);
    let (response_tx, response_rx) = mpsc::channel::<PreviewLoadResponse>();
    std::thread::spawn(move || {
        while let Ok(job) = request_rx.recv() {
            let path = job.request.path.clone();
            let data = loader(&job.request, &job.cancellation);
            let _ = response_tx.send(PreviewLoadResponse {
                target: job.target,
                generation: job.generation,
                path,
                data,
            });
        }
    });
    (request_tx, response_rx)
}

fn loading_preview_data(path: &Path) -> PreviewData {
    PreviewData {
        title: path
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("Preview")
            .to_string(),
        kind: PreviewKind::Unsupported,
        body: "Loading preview…".to_string(),
        document: None,
        spreadsheet: None,
        open_external: false,
    }
}

#[cfg(test)]
static NEXT_TEST_SEARCH_STORE_ID: AtomicU64 = AtomicU64::new(1);

#[cfg(test)]
fn test_search_store_path_in(project: &Path, process_id: u32, id: u64) -> PathBuf {
    project
        .join("target/test-state/ottrin-ui-search")
        .join(format!("{process_id}-{id}"))
        .join("search.db")
}

#[cfg(test)]
fn test_search_store_path() -> PathBuf {
    test_search_store_path_in(
        &std::env::current_dir().expect("Ottrin UI tests require the project directory"),
        std::process::id(),
        NEXT_TEST_SEARCH_STORE_ID.fetch_add(1, Ordering::Relaxed),
    )
}

#[cfg(unix)]
#[derive(Debug, Clone, PartialEq, Eq)]
struct AdministratorSessionIndexPaths {
    directory: PathBuf,
    store: PathBuf,
}

#[cfg(unix)]
fn administrator_session_index_paths_in(
    runtime: &Path,
    process_id: u32,
) -> AdministratorSessionIndexPaths {
    let directory = runtime
        .join("ottrin-administrator")
        .join(format!("session-{process_id}"));
    AdministratorSessionIndexPaths {
        store: directory.join("search.db"),
        directory,
    }
}

#[cfg(unix)]
fn remove_administrator_session_index_directory(
    paths: &AdministratorSessionIndexPaths,
) -> Result<(), String> {
    match std::fs::remove_dir_all(&paths.directory) {
        Ok(()) => Ok(()),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(format!(
            "Could not remove the Administrator session index at {}: {error}",
            path_label(&paths.directory)
        )),
    }
}

#[cfg(any(unix, test))]
fn administrator_session_search_config(config: &SearchConfig) -> Result<SearchConfig, String> {
    if config.include_roots.is_empty() {
        return Err(
            "Select at least one location before starting an Administrator session index."
                .to_string(),
        );
    }
    let mut session = config.clone();
    session.active_indexed_volume_roots.clear();
    session.content_indexing_enabled = false;
    session.content_include_roots.clear();
    session.content_exclude_roots.clear();
    Ok(session)
}

#[cfg(all(unix, not(test)))]
struct AdministratorSessionIndex {
    service: SearchService,
    paths: AdministratorSessionIndexPaths,
}

struct UiSearchService {
    #[cfg(all(any(unix, target_os = "windows"), not(test)))]
    client: Option<SearchDaemonClient>,
    #[cfg(all(unix, not(test)))]
    administrator_session: Option<AdministratorSessionIndex>,
    #[cfg(all(any(unix, target_os = "windows"), not(test)))]
    diagnostics_cache: Mutex<(Instant, SearchIndexDiagnostics)>,
    #[cfg(any(not(any(unix, target_os = "windows")), test))]
    local: SearchService,
}

impl UiSearchService {
    fn new(config: SearchConfig) -> Self {
        #[cfg(all(any(unix, target_os = "windows"), not(test)))]
        {
            // SAFETY: geteuid has no preconditions and no side effects.
            #[cfg(unix)]
            let required = daemon_connection_required(unsafe { libc::geteuid() });
            #[cfg(target_os = "windows")]
            let required = true;
            let client = required.then(|| {
                SearchDaemonClient::connect_default()
                    .expect("the package-owned index daemon path was validated before GUI startup")
            });
            let diagnostics = client.as_ref().map_or_else(
                || {
                    SearchIndexDiagnostics::unavailable(
                        "Administrator indexing is disabled until explicitly enabled".to_string(),
                    )
                },
                |client| {
                    client
                        .diagnostics()
                        .unwrap_or_else(SearchIndexDiagnostics::unavailable)
                },
            );
            let mut service = Self {
                client,
                #[cfg(unix)]
                administrator_session: None,
                diagnostics_cache: Mutex::new((Instant::now(), diagnostics)),
            };
            service.update_config(config);
            service
        }
        #[cfg(any(not(any(unix, target_os = "windows")), test))]
        {
            #[cfg(test)]
            {
                let store = test_search_store_path();
                Self {
                    local: SearchService::new_with_store_path(config, store),
                }
            }
            #[cfg(all(not(any(unix, target_os = "windows")), not(test)))]
            Self {
                local: SearchService::new(config),
            }
        }
    }

    fn start(&mut self) {
        #[cfg(any(not(any(unix, target_os = "windows")), test))]
        self.local.start();
    }

    fn stop(&mut self) {
        #[cfg(all(unix, not(test)))]
        if let Some(mut session) = self.administrator_session.take() {
            session.service.stop();
            let _ = remove_administrator_session_index_directory(&session.paths);
        }
        #[cfg(any(not(any(unix, target_os = "windows")), test))]
        self.local.stop();
    }

    #[cfg(all(unix, not(test)))]
    fn start_administrator_session_index(&mut self, config: &SearchConfig) -> Result<(), String> {
        // SAFETY: geteuid has no preconditions and no side effects.
        if unsafe { libc::geteuid() } != 0 {
            return Err(
                "Administrator session indexing is available only in an Administrator session."
                    .to_string(),
            );
        }
        if self.administrator_session.is_some() {
            return Ok(());
        }
        let config = administrator_session_search_config(config)?;
        let paths =
            administrator_session_index_paths_in(Path::new("/run/user/0"), std::process::id());
        let namespace = paths
            .directory
            .parent()
            .expect("Administrator session index has a namespace");
        std::fs::create_dir_all(namespace).map_err(|error| {
            format!("Could not create the private Administrator index namespace: {error}")
        })?;
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(namespace, std::fs::Permissions::from_mode(0o700)).map_err(
            |error| format!("Could not protect the Administrator index namespace: {error}"),
        )?;
        std::fs::create_dir(&paths.directory).map_err(|error| {
            format!("Could not create the private Administrator session index directory: {error}")
        })?;
        if let Err(error) =
            std::fs::set_permissions(&paths.directory, std::fs::Permissions::from_mode(0o700))
        {
            let _ = std::fs::remove_dir(&paths.directory);
            return Err(format!(
                "Could not protect the Administrator session index directory: {error}"
            ));
        }
        let mut service = SearchService::new_with_store_path(config, paths.store.clone());
        service.start();
        if let Some(error) = service
            .diagnostics()
            .last_error
            .filter(|_| service.handle().diagnostics().status == SearchIndexStatus::Unavailable)
        {
            service.stop();
            let _ = remove_administrator_session_index_directory(&paths);
            return Err(error);
        }
        *self.diagnostics_cache.lock().expect("search diagnostics") =
            (Instant::now(), service.diagnostics());
        self.client = None;
        self.administrator_session = Some(AdministratorSessionIndex { service, paths });
        Ok(())
    }

    #[cfg(all(unix, not(test)))]
    fn stop_administrator_session_index(&mut self) {
        if let Some(mut session) = self.administrator_session.take() {
            session.service.stop();
            let _ = remove_administrator_session_index_directory(&session.paths);
        }
    }

    #[cfg(any(not(unix), test))]
    fn stop_administrator_session_index(&mut self) {}

    #[cfg(all(unix, not(test)))]
    fn connect_administrator_persistent_index(&mut self) -> Result<(), String> {
        // SAFETY: geteuid has no preconditions and no side effects.
        if unsafe { libc::geteuid() } != 0 {
            return Err(
                "Persistent Administrator indexing is available only in an Administrator session."
                    .to_string(),
            );
        }
        let deadline = Instant::now() + Duration::from_secs(2);
        loop {
            if let Ok(client) = SearchDaemonClient::connect_default()
                && client.ping().is_ok()
            {
                let diagnostics = client.diagnostics()?;
                self.client = Some(client);
                *self.diagnostics_cache.lock().expect("search diagnostics") =
                    (Instant::now(), diagnostics);
                return Ok(());
            }
            if Instant::now() >= deadline {
                return Err("Persistent Administrator index service was enabled but its private socket did not become ready within 2 seconds.".to_string());
            }
            std::thread::sleep(Duration::from_millis(20));
        }
    }

    #[cfg(any(not(unix), test))]
    fn connect_administrator_persistent_index(&mut self) -> Result<(), String> {
        Err("Persistent Administrator indexing is available only on Unix.".to_string())
    }

    fn disconnect_administrator_persistent_index(&mut self) {
        #[cfg(all(unix, not(test)))]
        {
            self.client = None;
            *self.diagnostics_cache.lock().expect("search diagnostics") = (
                Instant::now(),
                SearchIndexDiagnostics::unavailable(
                    "Administrator indexing is disabled until explicitly enabled".to_string(),
                ),
            );
        }
    }

    #[cfg(any(not(unix), test))]
    fn start_administrator_session_index(&mut self, _config: &SearchConfig) -> Result<(), String> {
        Err("Administrator session indexing is available only on Unix.".to_string())
    }

    fn administrator_session_index_active(&self) -> bool {
        #[cfg(all(unix, not(test)))]
        return self.administrator_session.is_some();
        #[cfg(any(not(unix), test))]
        false
    }

    fn update_config(&mut self, config: SearchConfig) {
        #[cfg(all(unix, not(test)))]
        if self.administrator_session.is_some() {
            match administrator_session_search_config(&config) {
                Ok(config) => self
                    .administrator_session
                    .as_mut()
                    .expect("checked Administrator session")
                    .service
                    .update_config(config),
                Err(error) => {
                    if let Some(mut session) = self.administrator_session.take() {
                        session.service.stop();
                        let _ = remove_administrator_session_index_directory(&session.paths);
                    }
                    *self.diagnostics_cache.lock().expect("search diagnostics") =
                        (Instant::now(), SearchIndexDiagnostics::unavailable(error));
                }
            }
            return;
        }
        #[cfg(all(any(unix, target_os = "windows"), not(test)))]
        if let Some(client) = &self.client
            && let Err(error) = client.update_config(config)
        {
            self.record_daemon_error(error);
        }
        #[cfg(any(not(any(unix, target_os = "windows")), test))]
        self.local.update_config(config);
    }

    fn diagnostics(&self) -> SearchIndexDiagnostics {
        #[cfg(all(any(unix, target_os = "windows"), not(test)))]
        {
            let mut cache = self.diagnostics_cache.lock().expect("search diagnostics");
            #[cfg(unix)]
            if let Some(session) = &self.administrator_session {
                return session.service.diagnostics();
            }
            if cache.0.elapsed() >= Duration::from_millis(100) {
                let Some(client) = &self.client else {
                    return cache.1.clone();
                };
                match client.diagnostics() {
                    Ok(diagnostics) => *cache = (Instant::now(), diagnostics),
                    Err(error) => {
                        cache.0 = Instant::now();
                        cache.1.status = SearchIndexStatus::Unavailable;
                        cache.1.last_error = Some(error);
                    }
                }
            }
            cache.1.clone()
        }
        #[cfg(any(not(any(unix, target_os = "windows")), test))]
        {
            self.local.diagnostics()
        }
    }

    fn handle(&self) -> UiSearchHandle {
        #[cfg(all(any(unix, target_os = "windows"), not(test)))]
        {
            UiSearchHandle {
                remote: self.client.clone(),
                #[cfg(unix)]
                administrator_session: self
                    .administrator_session
                    .as_ref()
                    .map(|session| session.service.handle()),
            }
        }
        #[cfg(any(not(any(unix, target_os = "windows")), test))]
        {
            UiSearchHandle {
                local: self.local.handle(),
            }
        }
    }

    fn rebuild_index(&mut self) {
        #[cfg(all(any(unix, target_os = "windows"), not(test)))]
        {
            #[cfg(unix)]
            if let Some(session) = &mut self.administrator_session {
                session.service.rebuild_index();
                return;
            }
            if let Some(client) = self.client.clone() {
                std::thread::spawn(move || {
                    let _ = client.rebuild();
                });
            }
        }
        #[cfg(any(not(any(unix, target_os = "windows")), test))]
        self.local.rebuild_index();
    }

    fn clear_storage(&mut self) -> Result<u64, String> {
        #[cfg(all(any(unix, target_os = "windows"), not(test)))]
        {
            #[cfg(unix)]
            if let Some(mut session) = self.administrator_session.take() {
                let bytes = session.service.clear_storage()?;
                session.service.stop();
                remove_administrator_session_index_directory(&session.paths)?;
                return Ok(bytes);
            }
            let Some(client) = &self.client else {
                return Ok(0);
            };
            let bytes = client.clear_storage()?;
            client.shutdown()?;
            Ok(bytes)
        }
        #[cfg(any(not(any(unix, target_os = "windows")), test))]
        {
            self.local.clear_storage()
        }
    }

    #[cfg(all(any(unix, target_os = "windows"), not(test)))]
    fn record_daemon_error(&self, error: String) {
        let mut cache = self.diagnostics_cache.lock().expect("search diagnostics");
        cache.0 = Instant::now();
        cache.1.status = SearchIndexStatus::Unavailable;
        cache.1.last_error = Some(error);
    }
}

struct UiSearchHandle {
    #[cfg(all(any(unix, target_os = "windows"), not(test)))]
    remote: Option<SearchDaemonClient>,
    #[cfg(all(unix, not(test)))]
    administrator_session: Option<SearchHandle>,
    #[cfg(any(not(any(unix, target_os = "windows")), test))]
    local: SearchHandle,
}

impl UiSearchHandle {
    fn query_cancellable_with_diagnostics(
        &self,
        query: SearchQuery,
        cancelled: &AtomicBool,
    ) -> SearchQueryResult {
        #[cfg(all(any(unix, target_os = "windows"), not(test)))]
        {
            if cancelled.load(Ordering::Acquire) {
                return unavailable_search_result("Search cancelled".to_string());
            }
            #[cfg(unix)]
            if let Some(session) = &self.administrator_session {
                return session.query_cancellable_with_diagnostics(query, cancelled);
            }
            let Some(remote) = &self.remote else {
                return unavailable_search_result(
                    "Administrator indexing is disabled until explicitly enabled".to_string(),
                );
            };
            match remote.query_cancellable(query, cancelled) {
                Ok(result) if !cancelled.load(Ordering::Acquire) => result,
                Ok(_) => unavailable_search_result("Search cancelled".to_string()),
                Err(error) => unavailable_search_result(error),
            }
        }
        #[cfg(any(not(any(unix, target_os = "windows")), test))]
        {
            self.local
                .query_cancellable_with_diagnostics(query, cancelled)
        }
    }
}

#[cfg(all(any(unix, target_os = "windows"), not(test)))]
fn unavailable_search_result(error: String) -> SearchQueryResult {
    SearchQueryResult {
        response: SearchResponse {
            items: Vec::new(),
            total: 0,
            status: SearchIndexStatus::Unavailable,
            error: Some(error),
        },
        warning: None,
    }
}

#[cfg(unix)]
fn daemon_connection_required(effective_uid: u32) -> bool {
    effective_uid != 0
}

fn is_administrator_session() -> bool {
    #[cfg(unix)]
    {
        // SAFETY: geteuid has no preconditions and no side effects.
        unsafe { libc::geteuid() == 0 }
    }
    #[cfg(not(unix))]
    false
}

