    /// Poll the exact cache generation that supplies the DOCX inspector page.
    /// The caller owns painting the returned ready texture, so accessibility
    /// readiness cannot get ahead of egui's native image loader.
    fn cached_docx_raster_texture_load_result(
        &mut self,
        ctx: &Context,
        path: &Path,
        page_index: usize,
    ) -> Option<egui::load::TextureLoadResult> {
        let office_source_generation = ottrin_preview::office_preview_source_generation(path);
        let cache_key = preview_cache_key_for_page_with_generations(
            path,
            PREVIEW_CACHE_ORIGINAL,
            page_index,
            None,
            None,
            None,
            office_source_generation.as_ref(),
        );
        if !self.image_preview_cache.contains_key(&cache_key) {
            self.enqueue_image_preview(
                path,
                PreviewRequestTarget::Original,
                PREVIEW_CACHE_ORIGINAL,
                page_index,
                cache_key,
                PreviewJobSources {
                    office: office_source_generation,
                    ..Default::default()
                },
            );
            return None;
        }
        let bytes = self.image_preview_cache.get(&cache_key)?.bytes()?.to_vec();
        let uri = format!("bytes://preview/{cache_key}");
        ctx.include_bytes(uri.clone(), bytes);
        Some(ctx.try_load_texture(
            &uri,
            egui::TextureOptions::default(),
            egui::load::SizeHint::default(),
        ))
    }

    fn cached_original_image_zoom_widget_for_page(
        &mut self,
        path: &Path,
        zoom: f32,
        corner_radius: u8,
        page_index: usize,
    ) -> Option<egui::Image<'static>> {
        let sqlite_source_generation = ottrin_preview::is_sqlite_preview_candidate(path)
            .then(|| ottrin_preview::sqlite_preview_source_generation(path))
            .flatten();
        let obj_source_generation = ottrin_preview::is_obj_path(path)
            .then(|| ottrin_preview::obj_preview_source_generation(path))
            .flatten();
        let ply_source_generation = ottrin_preview::is_ply_path(path)
            .then(|| ottrin_preview::ply_preview_source_generation(path))
            .flatten();
        let office_source_generation = ottrin_preview::office_format_for_path(path)
            .is_some()
            .then(|| ottrin_preview::office_preview_source_generation(path))
            .flatten();
        let cache_key = preview_cache_key_for_page_with_generations(
            path,
            PREVIEW_CACHE_ORIGINAL,
            page_index,
            sqlite_source_generation.as_ref(),
            obj_source_generation.as_ref(),
            ply_source_generation.as_ref(),
            office_source_generation.as_ref(),
        );
        let video_source = (ottrin_preview::preview_profile(path).visual_renderer()
            == ottrin_preview::PreviewVisualRenderer::Video)
            .then(|| ottrin_preview::admit_video_thumbnail_source(path).ok())
            .flatten();
        let cache_key = self
            .office_provider_cache_key(
                path,
                PREVIEW_CACHE_ORIGINAL,
                page_index,
                office_source_generation.as_ref(),
            )
            .or_else(|| {
                video_source.as_ref().map(|source| {
                    ottrin_preview::video_thumbnail_cache_key(
                        source.generation(),
                        PREVIEW_CACHE_ORIGINAL,
                    )
                })
            })
            .unwrap_or(cache_key);
        self.discard_cached_pdf_preview_when_runtime_is_unavailable(path, &cache_key);
        if !self.image_preview_cache.contains_key(&cache_key) {
            self.enqueue_image_preview(
                path,
                PreviewRequestTarget::ZoomedOriginal,
                PREVIEW_CACHE_ORIGINAL,
                page_index,
                cache_key,
                PreviewJobSources {
                    sqlite: sqlite_source_generation,
                    obj: obj_source_generation,
                    ply: ply_source_generation,
                    office: office_source_generation,
                    office_provider: self.office_provider_for_path(path),
                    video: video_source,
                },
            );
            return None;
        }
        let bytes = self.image_preview_cache.get(&cache_key)?.bytes()?.to_vec();
        let decoded = image::load_from_memory(&bytes).ok()?;
        let size = Vec2::new(
            decoded.width() as f32 * zoom,
            decoded.height() as f32 * zoom,
        );
        Some(
            egui::Image::from_bytes(format!("bytes://preview/{cache_key}"), bytes)
                .fit_to_exact_size(size)
                .corner_radius(corner_radius),
        )
    }

    fn rotate_inspector_image(&mut self, path: &Path, clockwise: bool) {
        if !self.admit_mutation_paths(&[OperationPath::write(path.to_path_buf())]) {
            return;
        }
        let title = if clockwise {
            "Rotate image right"
        } else {
            "Rotate image left"
        };
        let op_id = self.queue_activity_record_with_recoverability(
            title,
            path_label(path),
            image_rotation_recoverability(),
        );
        match rotate_image_file(path, clockwise) {
            Ok(()) => {
                self.image_preview_cache.clear();
                if self.preview.path.as_deref() == Some(path) {
                    self.preview.data = None;
                    self.preview_load_slots[PreviewTarget::Overlay.index()].invalidate();
                    self.request_preview_load(
                        PreviewTarget::Overlay,
                        path.to_path_buf(),
                        EntryKind::File,
                    );
                }
                self.finish_operation_record(
                    op_id,
                    OperationStatus::Completed,
                    Some("Saved rotated image".to_string()),
                );
                self.set_status_message("Saved rotated image", true, 3);
            }
            Err(err) => {
                self.finish_operation_record(op_id, OperationStatus::Failed, Some(err.clone()));
                self.set_status_message(format!("Rotate failed: {err}"), false, 5);
            }
        }
    }

