    #[test]
    fn activity_headers_keep_status_visible_with_long_titles_and_scaled_text() {
        for width in [320.0, 420.0] {
            for scale in [1.0, 1.5, 2.0] {
                for (state, label) in [
                    (OperationStatus::Queued, "Queued"),
                    (OperationStatus::Completed, "Done"),
                    (OperationStatus::Stopped, "Stopped"),
                    (OperationStatus::NeedsReview, "Needs review"),
                ] {
                    let mut app = OttrinApp::default();
                    app.colors.font_scale = scale;
                    let short = app.queue_activity_record_with_recoverability(
                        "Move item",
                        "File moved",
                        OperationRecoverability::NotUndoable,
                    );
                    app.finish_operation_record(short, state, None);
                    let title =
                        "Move an unusually long file name into a deeply nested destination folder"
                            .repeat(3);
                    let id = app.queue_activity_record_with_recoverability(
                        title.clone(),
                        "/very/deep/destination/with/a/long/file/name".repeat(6),
                        OperationRecoverability::NotUndoable,
                    );
                    app.finish_operation_record(id, state, None);
                    let ctx = Context::default();
                    let mut frame = || {
                        ctx.run(
                            egui::RawInput {
                                screen_rect: Some(Rect::from_min_size(
                                    egui::Pos2::ZERO,
                                    egui::vec2(width, 3200.0),
                                )),
                                ..Default::default()
                            },
                            |ctx| {
                                egui::CentralPanel::default()
                                    .show(ctx, |ui| app.render_activity_sidebar(ui));
                            },
                        )
                    };
                    frame();
                    let output = frame();
                    let text_rect = |text: &str| {
                        output
                            .shapes
                            .iter()
                            .find_map(|shape| match &shape.shape {
                                egui::Shape::Text(item) if item.galley.job.text == text => Some((
                                    Rect::from_min_size(item.pos, item.galley.size()),
                                    shape.clip_rect,
                                    item.galley.job.wrap.max_width,
                                )),
                                _ => None,
                            })
                            .expect("Activity title and status must be rendered")
                    };
                    let badges = output
                        .shapes
                        .iter()
                        .filter_map(|shape| match &shape.shape {
                            egui::Shape::Text(item) if item.galley.job.text == label => {
                                Some(Rect::from_min_size(item.pos, item.galley.size()))
                            }
                            _ => None,
                        })
                        .collect::<Vec<_>>();
                    assert_eq!(badges.len(), 2);
                    assert!(
                        (badges[0].right() - badges[1].right()).abs() <= 0.5,
                        "Status edges differ between long and short cards at width {width}, scale {scale}: {badges:?}"
                    );
                    let (status, clip, _) = text_rect(label);
                    let (title, _, wrap_width) = text_rect(&title);
                    assert!(
                        clip.expand(0.5).contains_rect(status),
                        "Status clipped at width {width}, scale {scale}: {status:?} inside {clip:?}; title {title:?}, wrap width {wrap_width}"
                    );
                    assert!(
                        title.right() <= status.left(),
                        "Title overlaps status at width {width}, scale {scale}"
                    );
                }
            }
        }
    }

    #[cfg(target_os = "windows")]
    fn activity_frame(
        app: &mut OttrinApp,
        ctx: &Context,
        events: Vec<egui::Event>,
    ) -> egui::FullOutput {
        ctx.run(
            egui::RawInput {
                screen_rect: Some(Rect::from_min_size(
                    egui::Pos2::ZERO,
                    egui::vec2(900.0, 1000.0),
                )),
                events,
                ..Default::default()
            },
            |ctx| {
                egui::CentralPanel::default().show(ctx, |ui| app.render_activity_sidebar(ui));
                app.render_copy_cleanup_confirmation(ctx);
                app.render_copy_abort_confirmation(ctx);
            },
        )
    }

    #[cfg(target_os = "windows")]
    pub(super) fn activity_text(app: &mut OttrinApp, ctx: &Context) -> Vec<String> {
        activity_frame(app, ctx, Vec::new());
        activity_frame(app, ctx, Vec::new())
            .shapes
            .into_iter()
            .filter_map(|shape| match shape.shape {
                egui::Shape::Text(text) => Some(text.galley.job.text.clone()),
                _ => None,
            })
            .collect()
    }

    #[cfg(target_os = "windows")]
    pub(super) fn click_activity_action(
        app: &mut OttrinApp,
        ctx: &Context,
        label: &str,
    ) -> egui::FullOutput {
        let frame = |app: &mut OttrinApp, events| activity_frame(app, ctx, events);
        frame(app, Vec::new());
        let output = frame(app, Vec::new());
        let point = output
            .shapes
            .iter()
            .find_map(|shape| match &shape.shape {
                egui::Shape::Text(t) if t.galley.job.text == label => {
                    Some(Rect::from_min_size(t.pos, t.galley.size()).center())
                }
                _ => None,
            })
            .expect("The admitted Activity action must be rendered");
        frame(
            app,
            vec![
                egui::Event::PointerMoved(point),
                egui::Event::PointerButton {
                    pos: point,
                    button: egui::PointerButton::Primary,
                    pressed: true,
                    modifiers: Default::default(),
                },
            ],
        );
        frame(
            app,
            vec![egui::Event::PointerButton {
                pos: point,
                button: egui::PointerButton::Primary,
                pressed: false,
                modifiers: Default::default(),
            }],
        )
    }

    #[cfg(target_os = "windows")]
    #[test]
    #[ignore = "requires the native platform fixture test executable in an owned guest"]
    fn windows_copy_recovery_activity_integration() {
        const ROOT: &str = "OTTRIN_TEST_WINDOWS_COPY_ACTIVITY_ROOT";
        if let Some(root) = std::env::var_os(ROOT) {
            let root = PathBuf::from(root);
            let platform = std::env::var_os("OTTRIN_TEST_WINDOWS_PLATFORM_FIXTURE_EXE")
                .expect("fixture executable missing");
            let output = std::process::Command::new(platform)
                .args([
                    "--exact",
                    "copy_transaction::windows::journal::tests::windows_copy_activity_fixture",
                    "--ignored",
                    "--nocapture",
                ])
                .output()
                .unwrap();
            assert!(
                output.status.success(),
                "{}\n{}",
                String::from_utf8_lossy(&output.stdout),
                String::from_utf8_lossy(&output.stderr)
            );
            if std::env::var("OTTRIN_TEST_WINDOWS_COPY_ACTIVITY_CASE")
                .unwrap()
                .starts_with("abort-")
            {
                copy_activity_recovery::abort_test_case(&root);
                return;
            }
            if std::env::var("OTTRIN_TEST_WINDOWS_COPY_ACTIVITY_CASE")
                .unwrap()
                .starts_with("name-release")
            {
                copy_activity_recovery::name_release_test_case(&root);
                return;
            }
            if std::env::var("OTTRIN_TEST_WINDOWS_COPY_ACTIVITY_CASE")
                .unwrap()
                .starts_with("resume")
            {
                copy_activity_recovery::test_case(&root);
                return;
            }
            if std::env::var("OTTRIN_TEST_WINDOWS_COPY_ACTIVITY_CASE")
                .unwrap()
                .starts_with("cleanup")
            {
                copy_activity_cleanup::windows_test_case(&root);
                return;
            }
            let mut wrong = ottrin_platform::discover_retained_copy_transactions()
                .unwrap()
                .remove(0);
            let receipt = ottrin_platform::restore_retained_copy_undo_plan(
                wrong.transaction_id.as_deref().unwrap(),
            )
            .unwrap();
            wrong.transaction_id = Some("0".repeat(32));
            let rejected = windows_retained_copy_activity(wrong, Some(Ok(receipt)), None);
            assert!(
                rejected.receipt.is_none(),
                "A receipt must never attach to a different transaction row"
            );
            let mut app = OttrinApp::default();
            app.operation_history.clear();
            app.retained_copy_activity_loader =
                RetainedActivityLoader::spawn_with(load_retained_copy_activity);
            app.refresh_retained_copy_activity();
            fn wait(app: &mut OttrinApp) {
                let deadline = Instant::now() + Duration::from_secs(10);
                loop {
                    app.poll_path_move_undo_results();
                    app.poll_retained_copy_activity();
                    if !app.retained_copy_activity_loader.pending
                        && !app.operation_history.iter().any(|r| {
                            matches!(r.path_move_undo, Some(PathMoveUndoState::UndoQueued))
                        })
                    {
                        break;
                    }
                    assert!(Instant::now() < deadline, "Activity worker did not finish");
                    std::thread::sleep(Duration::from_millis(5));
                }
                assert!(app.retained_copy_activity_error.is_none());
            }
            let ctx = Context::default();
            fn click_undo(app: &mut OttrinApp, ctx: &Context, pending: bool) {
                click_activity_action(
                    app,
                    ctx,
                    if pending {
                        "Resume copy Undo"
                    } else {
                        "Undo copy"
                    },
                );
                assert!(matches!(
                    app.operation_history[0].path_move_undo,
                    Some(PathMoveUndoState::UndoQueued)
                ));
            }
            wait(&mut app);
            assert_eq!(app.operation_history.len(), 1);
            let id = app.operation_history[0].id;
            assert!(matches!(
                app.operation_history[0].path_move_undo,
                Some(PathMoveUndoState::Available)
            ));
            assert!(app.operation_history[0].path_move_undo_token.is_some());
            assert_eq!(
                copy_activity_cleanup::can_cleanup(&app.operation_history[0]),
                std::env::var("OTTRIN_TEST_WINDOWS_COPY_ACTIVITY_CASE").as_deref() != Ok("pending")
            );
            app.clear_finished_activity();
            assert_eq!(
                app.operation_history.len(),
                1,
                "Owned recovery must survive Clear finished"
            );
            let case = std::env::var("OTTRIN_TEST_WINDOWS_COPY_ACTIVITY_CASE").unwrap();
            let destination = std::env::var_os("OTTRIN_TEST_WINDOWS_COPY_ACTIVITY_DESTINATION")
                .map(PathBuf::from)
                .unwrap_or_else(|| root.join("fixture/destination"));
            let journal = std::fs::read_dir(&destination)
                .unwrap()
                .map(|e| e.unwrap().path())
                .find(|p| {
                    p.file_name()
                        .unwrap()
                        .to_string_lossy()
                        .starts_with(".ottrin-copy-")
                        && p.join("journal").is_file()
                })
                .unwrap()
                .join("journal");
            let before = std::fs::read(&journal).unwrap();
            let actual = if case == "moved" {
                let moved = destination.with_file_name("moved");
                std::fs::rename(&destination, &moved).unwrap();
                std::fs::create_dir(&destination).unwrap();
                std::fs::write(destination.join("copy"), b"unrelated new occupant").unwrap();
                moved
            } else {
                if case == "changed" {
                    std::fs::write(destination.join("copy/nested/file"), b"external data").unwrap();
                }
                destination.clone()
            };
            let registry = root.join("profile/Ottrin/State/copies");
            let central = std::fs::read_dir(&registry)
                .unwrap()
                .map(|entry| entry.unwrap().path())
                .find(|path| {
                    path.extension()
                        .is_some_and(|extension| extension == "copy-journal")
                })
                .unwrap();
            let central_before = std::fs::read(&central).unwrap();
            let data = actual.join("copy/nested/file");
            let mut blocked = case.strip_prefix("undo-blocked-").map(|target| {
                // Native receipts claim canonical spellings. Resolve this before
                // the oplock; alias equivalence is not lexical queue authority.
                let claim = std::fs::canonicalize(&data).unwrap();
                let payload_before = std::fs::read(&data).unwrap();
                let lock = crate::test_oplock::Oplock::request(match target {
                    "central" => &central,
                    "local" => &journal,
                    "payload" => &data,
                    _ => panic!("Unknown owned oplock target"),
                })
                .unwrap();
                (lock, payload_before, claim)
            });
            click_undo(&mut app, &ctx, case == "pending");
            if let Some((lock, payload_before, claim)) = &mut blocked {
                let broken = lock.wait_break();
                std::thread::sleep(Duration::from_millis(100));
                app.poll_path_move_undo_results();
                let pending = matches!(
                    app.operation_history[0].path_move_undo,
                    Some(PathMoveUndoState::UndoQueued)
                );
                let owns_paths = app
                    .activity_operation_conflict(u64::MAX, &[OperationPath::write(claim.clone())]);
                if pending {
                    click_activity_action(&mut app, &ctx, "Stop Undo");
                }
                let deadline = Instant::now() + Duration::from_secs(3);
                while app.copy_work.running(id) && Instant::now() < deadline {
                    app.poll_path_move_undo_results();
                    std::thread::sleep(Duration::from_millis(5));
                }
                let stopped = !app.copy_work.running(id);
                let close = lock.close();
                wait(&mut app);
                close.unwrap();
                assert_eq!(broken, windows_sys::Win32::Foundation::WAIT_OBJECT_0);
                assert!(
                    pending && owns_paths,
                    "Blocked Copy Undo must own its paths: pending={pending}, conflict={owns_paths}"
                );
                assert!(stopped, "Rendered Stop did not interrupt blocked Copy Undo");
                assert_eq!(std::fs::read(&journal).unwrap(), before);
                assert_eq!(std::fs::read(&central).unwrap(), central_before);
                assert_eq!(&std::fs::read(&data).unwrap(), payload_before);
                assert!(matches!(
                    app.operation_history[0].path_move_undo,
                    Some(PathMoveUndoState::Available)
                ));
                click_undo(&mut app, &ctx, false);
            }
            wait(&mut app);
            assert_eq!(app.operation_history[0].id, id);
            if case == "changed" {
                assert!(matches!(
                    app.operation_history[0].path_move_undo,
                    Some(PathMoveUndoState::Unavailable { .. })
                ));
                assert!(app.operation_history[0].path_move_undo_token.is_none());
                assert_eq!(
                    std::fs::read(destination.join("copy/nested/file")).unwrap(),
                    b"external data"
                );
                assert_eq!(std::fs::read(journal).unwrap(), before);
            } else {
                if case == "moved" {
                    // One admitted click must target the moved native parent,
                    // preserving the unrelated occupant of its former pathname.
                    assert_eq!(
                        std::fs::read(destination.join("copy")).unwrap(),
                        b"unrelated new occupant"
                    );
                }
                assert!(matches!(
                    app.operation_history[0].path_move_undo,
                    Some(PathMoveUndoState::Undone)
                ));
                assert!(!actual.join("copy").exists());
                let retained = app.operation_history[0]
                    .path_move_undo_token
                    .as_ref()
                    .unwrap()
                    .receipt
                    .before_path();
                assert_eq!(
                    std::fs::read(retained.join("nested/file")).unwrap(),
                    b"original data"
                );
                app.clear_finished_activity();
                assert_eq!(app.operation_history.len(), 1);
            }
            drop(app);
            return;
        }
        for case in [
            "abort-staging",
            "abort-changed-controls",
            "success",
            "changed",
            "moved",
            "pending",
            "undo-blocked-central",
            "undo-blocked-local",
            "undo-blocked-payload",
            "name-release",
            "name-release-stopped",
            "name-release-changed",
            "resume-staged",
            "resume-finalizing",
            "resume-changed",
            "resume-moved",
            "resume-stopped",
            "resume-blocked-central",
            "resume-blocked-local",
            "resume-blocked-payload",
            "cleanup-blocked-central",
            "cleanup-blocked-local",
            "cleanup-blocked-payload",
            "cleanup-success",
            "cleanup-changed",
            "cleanup-retry",
            "cleanup-stopped-metadata",
            "cleanup-cohort",
            "cleanup-cohort-partial",
        ] {
            let root = tempfile::tempdir().unwrap();
            let destination_root = std::env::var_os("OTTRIN_TEST_WINDOWS_COPY_ACTIVITY_VOLUME")
                .map(|volume| tempfile::tempdir_in(PathBuf::from(volume)).unwrap());
            std::fs::create_dir(root.path().join("userprofile")).unwrap();
            let mut command = std::process::Command::new(std::env::current_exe().unwrap());
            command
                .args([
                    "--exact",
                    "tests::windows_copy_recovery_activity_integration",
                    "--ignored",
                    "--nocapture",
                ])
                .current_dir(root.path())
                .env(ROOT, root.path())
                .env("OTTRIN_TEST_WINDOWS_COPY_ACTIVITY_CASE", case)
                .env("LOCALAPPDATA", root.path().join("profile"))
                .env("APPDATA", root.path().join("roaming"))
                .env("USERPROFILE", root.path().join("userprofile"));
            if let Some(destination_root) = &destination_root {
                command.env(
                    "OTTRIN_TEST_WINDOWS_COPY_ACTIVITY_DESTINATION",
                    destination_root.path().join("destination"),
                );
            } else {
                command.env_remove("OTTRIN_TEST_WINDOWS_COPY_ACTIVITY_DESTINATION");
            }
            let output = command.output().unwrap();
            assert!(
                output.status.success(),
                "{case}: {}\n{}",
                String::from_utf8_lossy(&output.stdout),
                String::from_utf8_lossy(&output.stderr)
            );
        }
    }

    #[cfg(target_os = "windows")]
    #[test]
    fn windows_retained_copy_activity_missing_registry_worker_is_read_only() {
        const FIXTURE: &str = "OTTRIN_COPY_ACTIVITY_EMPTY_FIXTURE";
        if let Some(root) = std::env::var_os(FIXTURE) {
            let root = PathBuf::from(root);
            assert_eq!(
                std::env::var_os("LOCALAPPDATA"),
                Some(root.clone().into_os_string())
            );
            let mut loader = RetainedActivityLoader::spawn_with(load_retained_copy_activity);
            loader.request().unwrap();
            let deadline = Instant::now() + Duration::from_secs(5);
            loop {
                if let Some(result) = loader.poll() {
                    let (entries, error) = result.unwrap();
                    assert!(entries.is_empty());
                    assert!(error.is_none(), "{error:?}");
                    break;
                }
                assert!(Instant::now() < deadline, "Discovery worker timed out");
                std::thread::yield_now();
            }
            assert!(!root.join("Ottrin").exists());
            return;
        }
        let root = tempfile::tempdir().unwrap();
        let output = std::process::Command::new(std::env::current_exe().unwrap())
            .args([
                "--exact",
                "tests::windows_retained_copy_activity_missing_registry_worker_is_read_only",
                "--nocapture",
            ])
            .env(FIXTURE, root.path())
            .env("LOCALAPPDATA", root.path())
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "{}\n{}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        assert_eq!(std::fs::read_dir(root.path()).unwrap().count(), 0);
    }

    #[cfg(target_os = "windows")]
    #[test]
    fn windows_retained_copy_activity_keeps_evidence_and_actions_separate() {
        use ottrin_platform::{WindowsCopyPhase as Phase, WindowsCopyRecoveryEvidence as Evidence};
        for phase in [
            Phase::Staging,
            Phase::Aborted,
            Phase::Staged,
            Phase::PlanningPermissions,
            Phase::ReadyToPublish,
            Phase::RetainingOriginal,
            Phase::PublicationPending,
            Phase::ApplyingPermissions,
            Phase::Finalizing,
            Phase::Completed,
            Phase::UndoPending,
            Phase::Undone,
            Phase::CleaningUp,
        ] {
            for evidence in [
                Evidence::VerifiedTree,
                Evidence::VerifiedOriginal,
                Evidence::VerifiedCleanup,
                Evidence::UnverifiedStage,
                Evidence::NeedsReview {
                    reason: "changed retained bytes".into(),
                },
            ] {
                let undone = phase == Phase::Undone
                    && matches!(
                        evidence,
                        Evidence::VerifiedTree | Evidence::VerifiedOriginal
                    );
                let review = matches!(evidence, Evidence::NeedsReview { .. });
                let activity = windows_retained_copy_activity(
                    ottrin_platform::WindowsRetainedCopyStatus {
                        transaction_id: Some("a".repeat(32)),
                        phase: Some(phase),
                        publication: Some(PathBuf::from(r"C:\old\copy")),
                        retained: Some(PathBuf::from(r"C:\old\candidate")),
                        owned_location: Some(PathBuf::from(r"C:\moved\actual")),
                        transaction: Some(PathBuf::from(r"C:\moved\journal")),
                        source_label: None,
                        evidence,
                    },
                    None,
                    None,
                );
                assert!(activity.receipt.is_none());
                assert_eq!(activity.title(), "Copy from previous session");
                assert!(restored_copy_token(activity.receipt.clone()).is_none());
                assert!(!path_move_undo_action_is_available(
                    restored_copy_status(&activity.undo),
                    Some(&activity.undo)
                ));
                assert_eq!(
                    activity.ownership.recovery_location.as_deref(),
                    Some(Path::new(r"C:\moved\journal"))
                );
                assert!(activity.detail.contains(r"C:\moved\actual"));
                assert!(!activity.detail.contains(r"C:\old"));
                assert!(activity.detail.contains(&"a".repeat(32)));
                assert_eq!(activity.ownership.transactions, vec!["a".repeat(32)]);
                assert!(activity.ownership.restored);
                assert!(activity.ownership.finalization.is_none());
                assert_eq!(matches!(activity.undo, PathMoveUndoState::Undone), undone);
                if review {
                    assert!(
                        matches!(activity.undo, PathMoveUndoState::Unavailable { ref reason } if reason == "changed retained bytes")
                    );
                }
            }
        }
        let unknown = windows_retained_copy_activity(
            ottrin_platform::WindowsRetainedCopyStatus {
                transaction_id: Some("b".repeat(32)),
                phase: None,
                publication: None,
                retained: None,
                owned_location: None,
                transaction: None,
                source_label: None,
                evidence: Evidence::NeedsReview {
                    reason: "invalid journal".into(),
                },
            },
            None,
            None,
        );
        assert!(unknown.detail.contains("Copy journal needs review"));
        assert!(unknown.detail.contains(&"b".repeat(32)));
        assert!(!unknown.detail.contains("Data:"));
        use std::os::windows::ffi::OsStringExt;
        let mut keys = HashSet::new();
        for surrogate in [0xd800, 0xd801] {
            let mut units = r"C:\state\".encode_utf16().collect::<Vec<_>>();
            units.push(surrogate);
            units.extend(".COPY-JOURNAL".encode_utf16());
            let entry = ottrin_platform::WindowsRetainedCopyStatus {
                transaction_id: None,
                phase: None,
                publication: None,
                retained: None,
                owned_location: None,
                transaction: Some(PathBuf::from(std::ffi::OsString::from_wide(&units))),
                source_label: None,
                evidence: Evidence::NeedsReview {
                    reason: "Unrecognized recovery filename".into(),
                },
            };
            assert!(!windows_copy_can_admit(&entry));
            assert!(!windows_copy_can_resume(&entry));
            let activity = windows_retained_copy_activity(entry, None, None);
            assert!(activity.ownership.transactions.is_empty());
            assert_eq!(activity.title(), "Copy recovery record needs review");
            assert!(activity.receipt.is_none() && activity.ownership.recovery.is_none());
            assert!(activity.ownership.recovery_location.is_some());
            assert!(!activity.detail.contains("Transaction:"));
            keys.insert(activity.ownership.key);
        }
        assert_eq!(
            keys.len(),
            2,
            "Native names must retain distinct review rows"
        );

        let root = tempfile::tempdir().unwrap();
        let journal = root.path().join("Ångström recovery record");
        std::fs::write(&journal, b"retained recovery bytes").unwrap();
        let activity = windows_retained_copy_activity(
            ottrin_platform::WindowsRetainedCopyStatus {
                transaction_id: Some("c".repeat(32)),
                phase: Some(Phase::Staging),
                publication: None,
                retained: None,
                owned_location: None,
                transaction: Some(journal.clone()),
                source_label: None,
                evidence: Evidence::UnverifiedStage,
            },
            None,
            None,
        );
        let mut app = OttrinApp::default();
        app.operation_history.clear();
        app.merge_retained_copy_activity(vec![activity]);
        let ctx = Context::default();
        ctx.style_mut(|style| style.animation_time = 0.0);
        click_activity_action(&mut app, &ctx, "Recovery details");
        let texts = activity_text(&mut app, &ctx);
        assert!(texts.iter().any(|text| text == "Recovery location"));
        assert!(
            texts
                .iter()
                .any(|text| text.contains("Resume and automatic cleanup are unavailable"))
        );
        assert!(
            !texts
                .iter()
                .any(|text| text == "Resume copy" || text == "Clear retained Copy data")
        );
        let output = click_activity_action(&mut app, &ctx, "Copy recovery path");
        assert!(output.platform_output.commands.iter().any(|command| {
            matches!(command, egui::OutputCommand::CopyText(text) if text == journal.to_str().unwrap())
        }));
        assert_eq!(std::fs::read(&journal).unwrap(), b"retained recovery bytes");
        assert_eq!(app.operation_history.len(), 1);
        assert!(!app.copy_recovery.running() && !app.copy_cleanup.running());
        assert!(!copy_activity_recovery::can_recover(
            &app.operation_history[0]
        ));
        app.merge_retained_copy_activity(Vec::new());
        assert!(
            app.operation_history[0]
                .retained_copy
                .as_ref()
                .unwrap()
                .recovery_location
                .is_none()
        );
    }

    #[test]
    fn image_rotation_reports_that_undo_is_unavailable() {
        let recoverability = image_rotation_recoverability();
        let (label, _, explanation) = operation_recoverability_label(
            recoverability,
            Colors::preset(ThemePreset::Ottrin, true),
        );

        assert_eq!(recoverability, OperationRecoverability::NotUndoable);
        assert_eq!(label, "Not undoable");
        assert!(explanation.contains("original image bytes"));
    }

    #[test]
    fn retained_move_recovery_reports_that_undo_is_unavailable() {
        let command = FileCommand::RecoverRetainedMove {
            transaction_id: [0_u8; 16],
        };

        assert_eq!(
            operation_recoverability(&command),
            OperationRecoverability::NotUndoable
        );
    }

    #[test]
    fn windows_retained_move_activity_exposes_both_transaction_kinds() {
        for (kind, phase) in [
            (
                WindowsMoveTransactionKind::SameVolumeOverwrite,
                "same-volume overwrite",
            ),
            (WindowsMoveTransactionKind::CrossVolume, "cross-volume"),
        ] {
            let activity = windows_retained_move_activity(
                ottrin_platform::move_recovery::WindowsDiscoveredMoveTransaction {
                    transaction_id: [0x22; 16],
                    kind,
                    undo_status: ottrin_platform::move_recovery::WindowsMoveUndoStatus::NotStarted,
                },
            );
            assert_eq!(activity.recovery, RetainedMoveRecovery::Forward);
            assert_eq!(activity.phase, phase);
        }
    }

    #[test]
    fn windows_retained_move_activity_distinguishes_pending_and_completed_undo() {
        use ottrin_platform::move_recovery::WindowsMoveUndoStatus;
        for (kind, pending_phase, complete_phase) in [
            (
                WindowsMoveTransactionKind::SameVolumeOverwrite,
                "Replace Undo pending",
                "Replace undone",
            ),
            (
                WindowsMoveTransactionKind::CrossVolume,
                "Cross-volume Undo pending",
                "Cross-volume Move undone",
            ),
        ] {
            for (undo_status, phase, recovery, label) in [
                (
                    WindowsMoveUndoStatus::Pending,
                    pending_phase,
                    RetainedMoveRecovery::Undo,
                    Some("Resume Undo"),
                ),
                (
                    WindowsMoveUndoStatus::Complete,
                    complete_phase,
                    RetainedMoveRecovery::Undone,
                    None,
                ),
            ] {
                let activity = windows_retained_move_activity(
                    ottrin_platform::move_recovery::WindowsDiscoveredMoveTransaction {
                        transaction_id: [0x23; 16],
                        kind,
                        undo_status,
                    },
                );
                assert_eq!(activity.phase, phase);
                assert_eq!(activity.recovery, recovery);
                assert_eq!(activity.recovery.action_label(), label);
            }
        }
    }

