    fn wait_for_transfer_probe(app: &mut OttrinApp) {
        let deadline = Instant::now() + Duration::from_secs(5);
        while app
            .pending_transfer_conflict
            .as_ref()
            .is_some_and(|pending| pending.probe.is_some())
        {
            assert!(Instant::now() < deadline, "destination probe timed out");
            app.poll_transfer_probe_results();
            std::thread::sleep(Duration::from_millis(5));
        }
    }

    fn clipboard_keyboard_fixture() -> (tempfile::TempDir, OttrinApp, PathBuf) {
        // File transfers require a home or discovered-volume binding. /tmp is
        // neither, even though it is a valid location for other test fixtures.
        let root = tempfile::Builder::new()
            .prefix(".ottrin-clipboard-test-")
            .tempdir_in(default_home_dir())
            .unwrap();
        let source = root.path().join("source.txt");
        std::fs::write(&source, "clipboard fixture").unwrap();
        let mut app = OttrinApp::default();
        app.state.active_tab_mut().current_dir = root.path().to_path_buf();
        let tab_id = app.state.active_tab().id;
        let ui = app.tab_ui.entry(tab_id).or_default();
        ui.main.entries = vec![FileEntry {
            name: "source.txt".to_string(),
            path: source.clone(),
            kind: EntryKind::File,
            is_executable: false,
            symlink_target_is_dir: None,
            size_bytes: Some(17),
            modified_unix_secs: None,
        }];
        ui.main_sel = Some(0);
        (root, app, source)
    }

    #[test]
    fn breadcrumb_click_navigates_while_blank_address_space_enters_editing() {
        let (root, mut app, _) = clipboard_keyboard_fixture();
        let child = root.path().join("nested/child");
        std::fs::create_dir_all(&child).unwrap();
        app.state.active_tab_mut().current_dir = child;
        app.state.active_tab_mut().view_mode = ViewMode::List;
        let tab_id = app.state.active_tab().id;
        let ctx = Context::default();
        let draw = |app: &mut OttrinApp, events: Vec<egui::Event>| {
            ctx.run(
                egui::RawInput {
                    screen_rect: Some(Rect::from_min_size(
                        egui::Pos2::ZERO,
                        Vec2::new(900.0, 100.0),
                    )),
                    events,
                    ..Default::default()
                },
                |ctx| {
                    egui::CentralPanel::default().show(ctx, |ui| {
                        app.render_address_bar(ui, tab_id);
                    });
                },
            )
        };
        let output = draw(&mut app, Vec::new());
        let name = root.path().file_name().unwrap().to_str().unwrap();
        let point = output
            .shapes
            .iter()
            .find_map(|shape| match &shape.shape {
                egui::Shape::Text(text) if text.galley.job.text.ends_with(name) => {
                    Some(Rect::from_min_size(text.pos, text.galley.size()).center())
                }
                _ => None,
            })
            .expect("actual parent breadcrumb label");
        let click = |pos| {
            vec![
                egui::Event::PointerMoved(pos),
                egui::Event::PointerButton {
                    pos,
                    button: egui::PointerButton::Primary,
                    pressed: true,
                    modifiers: egui::Modifiers::NONE,
                },
                egui::Event::PointerButton {
                    pos,
                    button: egui::PointerButton::Primary,
                    pressed: false,
                    modifiers: egui::Modifiers::NONE,
                },
            ]
        };
        let _ = draw(&mut app, click(point));
        assert_eq!(app.state.active_tab().current_dir, root.path());
        assert!(!app.address_bar_state(tab_id).is_some_and(|bar| bar.editing));
        let _ = draw(&mut app, Vec::new());
        let _ = draw(&mut app, click(egui::pos2(870.0, point.y)));
        assert!(app.address_bar_state(tab_id).is_some_and(|bar| bar.editing));
        assert_eq!(
            app.address_bar_state(tab_id).unwrap().text,
            root.path().display().to_string()
        );
    }

    #[test]
    fn breadcrumb_navigation_reveals_a_destination_left_of_the_old_viewport() {
        let root = tempfile::tempdir().unwrap();
        let deep = root.path().join("one/two/three/four/five");
        std::fs::create_dir_all(&deep).unwrap();
        let mut app = OttrinApp::default();
        app.state.active_tab_mut().view_mode = ViewMode::Miller;
        app.sidebar = SidebarSection::None;
        app.open_directory_at_startup(deep);
        let tab_id = app.state.active_tab().id;
        let ctx = Context::default();
        let mut destination_button = None;
        for frame in 0..180 {
            app.poll_listing_results();
            let events = if frame == 90 {
                let pos = destination_button.expect("visible ancestor breadcrumb");
                vec![
                    egui::Event::PointerMoved(pos),
                    egui::Event::PointerButton {
                        pos,
                        button: egui::PointerButton::Primary,
                        pressed: true,
                        modifiers: egui::Modifiers::NONE,
                    },
                    egui::Event::PointerButton {
                        pos,
                        button: egui::PointerButton::Primary,
                        pressed: false,
                        modifiers: egui::Modifiers::NONE,
                    },
                ]
            } else {
                Vec::new()
            };
            let output = ctx.run(
                egui::RawInput {
                    screen_rect: Some(Rect::from_min_size(
                        egui::Pos2::ZERO,
                        Vec2::new(1100.0, 690.0),
                    )),
                    time: Some(frame as f64 / 60.0),
                    events,
                    ..Default::default()
                },
                |ctx| {
                    egui::TopBottomPanel::top("test_address").show(ctx, |ui| {
                        app.render_address_bar(ui, tab_id);
                    });
                    egui::CentralPanel::default().show(ctx, |ui| {
                        app.render_miller(ui, tab_id);
                    });
                },
            );
            if frame == 89 {
                assert!(app.tab_ui[&tab_id].miller_h_offset > 500.0);
                let name = root.path().file_name().unwrap().to_str().unwrap();
                destination_button = output.shapes.iter().find_map(|shape| match &shape.shape {
                    egui::Shape::Text(text) if text.galley.job.text.ends_with(name) => {
                        Some(Rect::from_min_size(text.pos, text.galley.size()).center())
                    }
                    _ => None,
                });
            }
            std::thread::sleep(Duration::from_millis(1));
        }
        assert_eq!(app.state.active_tab().current_dir, root.path());
        assert!(
            app.tab_ui[&tab_id].miller_current_visible,
            "ancestor navigation must reveal its file column, not leave the old horizontal offset"
        );
    }

