    #[test]
    fn delete_shortcut_uses_press_modifiers_instead_of_the_end_of_frame_state() {
        for (pressed_modifiers, final_modifiers, expected_mode) in [
            (
                egui::Modifiers::SHIFT,
                egui::Modifiers::NONE,
                DeleteMode::Permanent,
            ),
            (
                egui::Modifiers::NONE,
                egui::Modifiers::SHIFT,
                DeleteMode::Trash,
            ),
            (
                egui::Modifiers::NONE,
                egui::Modifiers::NONE,
                DeleteMode::Trash,
            ),
        ] {
            let (_root, mut app, source) = clipboard_keyboard_fixture();
            app.select_all();
            let ctx = Context::default();
            let _ = ctx.run(
                egui::RawInput {
                    modifiers: final_modifiers,
                    events: vec![
                        egui::Event::Key {
                            key: Key::Delete,
                            physical_key: None,
                            pressed: true,
                            repeat: false,
                            modifiers: pressed_modifiers,
                        },
                        egui::Event::Key {
                            key: Key::Delete,
                            physical_key: None,
                            pressed: false,
                            repeat: false,
                            modifiers: final_modifiers,
                        },
                    ],
                    ..Default::default()
                },
                |ctx| app.handle_keyboard(ctx),
            );
            let pending = app.pending_delete.as_ref().expect("delete confirmation");
            assert_eq!(pending.requested_mode, expected_mode);
            assert_eq!(pending.targets, vec![source.clone()]);
            assert!(source.exists(), "shortcuts must still require confirmation");
        }
    }

    #[test]
    fn file_shortcuts_respect_input_ownership() {
        for owner in ["files", "search", "text", "inspector", "command", "address"] {
            for key in [Key::A, Key::F2, Key::Delete] {
                let (_root, mut app, source) = clipboard_keyboard_fixture();
                app.state.active_tab_mut().view_mode = ViewMode::List;
                let ctx = Context::default();
                match owner {
                    "search" => {
                        app.sidebar = SidebarSection::Search;
                        app.search_ui.input_focused = true;
                    }
                    "text" => {
                        let _ = ctx.run(Default::default(), |ctx| {
                            egui::CentralPanel::default().show(ctx, |ui| {
                                ui.text_edit_singleline(&mut String::new()).request_focus();
                            });
                        });
                        assert!(ctx.wants_keyboard_input());
                    }
                    "inspector" => app.preview.visible = true,
                    "command" => app.command_frame.visible = true,
                    "address" => {
                        app.address_bars
                            .entry(app.state.active_tab().id)
                            .or_default()
                            .editing = true;
                    }
                    "files" => {}
                    _ => unreachable!(),
                }
                let modifiers = if key == Key::A {
                    egui::Modifiers::CTRL
                } else {
                    egui::Modifiers::NONE
                };
                let _ = ctx.run(
                    egui::RawInput {
                        modifiers,
                        events: vec![egui::Event::Key {
                            key,
                            physical_key: None,
                            pressed: true,
                            repeat: false,
                            modifiers,
                        }],
                        ..Default::default()
                    },
                    |ctx| app.handle_keyboard(ctx),
                );
                let invoked = match key {
                    Key::A => app.tab_ui[&app.state.active_tab().id]
                        .selected_paths
                        .contains(&source),
                    Key::F2 => app.pending_rename.is_some(),
                    Key::Delete => app.pending_delete.is_some(),
                    _ => unreachable!(),
                };
                assert_eq!(invoked, owner == "files", "{key:?} belongs to {owner}");
                assert!(
                    source.exists(),
                    "keyboard handling must not bypass confirmation"
                );
            }
        }
    }

