    fn ready_docx_test_raster(color: [u8; 4]) -> Vec<u8> {
        ready_docx_test_raster_with_dimensions(2, 2, color)
    }

    fn ready_docx_test_raster_with_dimensions(width: u32, height: u32, color: [u8; 4]) -> Vec<u8> {
        let mut png = Vec::new();
        image::RgbaImage::from_pixel(width, height, image::Rgba(color))
            .write_to(&mut std::io::Cursor::new(&mut png), image::ImageFormat::Png)
            .expect("encode ready DOCX raster");
        png
    }

    fn set_docx_quick_inspector_state(app: &mut OttrinApp, path: &Path) {
        app.preview.visible = true;
        app.preview.path = Some(path.to_path_buf());
        app.preview.data = Some(PreviewData {
            title: path
                .file_name()
                .and_then(|name| name.to_str())
                .unwrap_or("report.docx")
                .to_string(),
            kind: PreviewKind::OfficeMetadata,
            body: "Filetype: DOCX document".to_string(),
            document: None,
            spreadsheet: None,
            open_external: true,
        });
        app.preview.visual_fit = true;
        app.preview.visual_zoom = 1.0;
    }

    struct ControlledDocxImageLoader {
        ready: Arc<AtomicBool>,
    }

    impl egui::load::ImageLoader for ControlledDocxImageLoader {
        fn id(&self) -> &str {
            "ottrin-ui::tests::ControlledDocxImageLoader"
        }

        fn load(
            &self,
            ctx: &Context,
            uri: &str,
            _: egui::load::SizeHint,
        ) -> egui::load::ImageLoadResult {
            let bytes = match ctx.try_load_bytes(uri)? {
                egui::load::BytesPoll::Ready { bytes, .. } => bytes,
                egui::load::BytesPoll::Pending { size } => {
                    return Ok(egui::load::ImagePoll::Pending { size });
                }
            };
            let decoded = image::load_from_memory(&bytes)
                .map_err(|error| egui::load::LoadError::Loading(error.to_string()))?
                .into_rgba8();
            if !self.ready.load(Ordering::SeqCst) {
                return Ok(egui::load::ImagePoll::Pending { size: None });
            }
            let size = [decoded.width() as usize, decoded.height() as usize];
            Ok(egui::load::ImagePoll::Ready {
                image: Arc::new(egui::ColorImage::from_rgba_unmultiplied(
                    size,
                    decoded.as_raw(),
                )),
            })
        }

        fn forget(&self, _: &str) {}

        fn forget_all(&self) {}

        fn byte_size(&self) -> usize {
            0
        }
    }

