    #[cfg(target_os = "linux")]
    #[test]
    fn linux_move_recovery_queues_captured_paths_and_executes_bound_worker() {
        use ottrin_platform::move_recovery::{
            LinuxFileType, LinuxJournalDirectory, LinuxSourceParentDirectory, LinuxStableIdentity,
            PreparedRecord,
        };
        use std::os::unix::fs::MetadataExt;
        let fixture = tempfile::tempdir().unwrap();
        let root = fixture.path().join("central");
        let parent_path = fixture.path().join("source-parent");
        let destination = fixture.path().join("destination");
        for path in [&root, &parent_path, &destination] {
            std::fs::create_dir(path).unwrap();
        }
        let id = [0x92; 16];
        let local_name = Path::new(".ottrin-move-92929292929292929292929292929292");
        let local_path = parent_path.join(local_name);
        std::fs::create_dir(&local_path).unwrap();
        let source = parent_path.join("original.txt");
        std::fs::write(&source, b"source payload").unwrap();
        let identity = |path: &Path, kind| {
            let m = std::fs::symlink_metadata(path).unwrap();
            LinuxStableIdentity::new(m.dev(), m.ino(), kind)
        };
        let parent = LinuxSourceParentDirectory::open(&parent_path).unwrap();
        let local_id = identity(&local_path, LinuxFileType::Directory);
        let local = parent
            .open_existing_transaction(local_name, local_id)
            .unwrap();
        let central = LinuxJournalDirectory::open_configured(&root).unwrap();
        let prepared = PreparedRecord::new_linux(
            id,
            &parent_path,
            Path::new("original.txt"),
            identity(&parent_path, LinuxFileType::Directory),
            identity(&source, LinuxFileType::Regular),
            local_name,
            local_id,
        )
        .unwrap();
        {
            let mut lock = central.try_lock_recovery().unwrap();
            lock.prepare_with_local(&local, &prepared).unwrap();
            lock.advance_to_claim_intent_with_local(&local, &prepared)
                .unwrap();
            lock.claim_source_after_intent(&parent, &local, id).unwrap();
            lock.advance_to_claimed_with_local(&local, id).unwrap();
            lock.advance_to_pending_destination_with_local(
                &local,
                id,
                &destination.join("original.txt"),
            )
            .unwrap();
        }
        drop((local, parent, central));
        let plan = NativeMoveRecoveryPlan::capture_at(&root, id).unwrap();
        let paths = plan.paths().to_vec();
        let mut app = OttrinApp::default();
        app.retained_move_activity = vec![RetainedMoveActivity {
            transaction_id: id,
            phase: "pending destination",
            recovery: RetainedMoveRecovery::Forward,
            plan: Some(plan),
        }];
        assert!(app.run_file_op_bound(
            FileCommand::RecoverRetainedMove { transaction_id: id },
            None,
            Vec::new(),
            None,
            None,
            None
        ));
        assert_eq!(
            app.operation_history.front().unwrap().operation_paths,
            paths
                .into_iter()
                .map(OperationPath::write)
                .collect::<Vec<_>>()
        );
        for path in [&source, &destination, &local_path, &root] {
            assert!(app.activity_paths_conflict(u64::MAX, &[(path.as_path(), path.as_path())]));
        }
        assert!(
            !app.activity_paths_conflict(
                u64::MAX,
                &[(Path::new("/outside"), Path::new("/outside"))]
            )
        );
        let result = app.op_rx.recv_timeout(Duration::from_secs(10)).unwrap();
        assert!(result.error.is_none(), "{:?}", result.error);
        app.op_tx.send(result).unwrap();
        app.poll_op_results();
        assert_eq!(
            app.operation_history.front().unwrap().status,
            OperationStatus::Completed
        );
        assert_eq!(std::fs::read(&source).unwrap(), b"source payload");
        assert!(!local_path.exists());
        assert!(!app.activity_paths_conflict(u64::MAX, &[(source.as_path(), source.as_path())]));
    }

    #[cfg(target_os = "windows")]
    #[test]
    fn windows_move_recovery_requires_captured_paths_and_real_drive_bindings() {
        if private_activity_process(
            "windows_move_recovery_requires_captured_paths_and_real_drive_bindings",
        ) {
            return;
        }
        let mut app = OttrinApp::default();
        let unknown = FileCommand::RecoverRetainedMove {
            transaction_id: [0x7c; 16],
        };
        assert!(!app.run_file_op_bound(unknown, None, Vec::new(), None, None, None));
        assert!(app.operation_history.is_empty());

        let fixture = tempfile::tempdir().unwrap();
        let source_parent = fixture.path().join("source");
        let destination = fixture.path().join("destination");
        std::fs::create_dir(&source_parent).unwrap();
        std::fs::create_dir(&destination).unwrap();
        let source = source_parent.join("entry.txt");
        std::fs::write(&source, b"selected source").unwrap();
        std::fs::write(destination.join("entry.txt"), b"displaced destination").unwrap();
        let (_, receipt) = DefaultPlatform
            .execute_move_with_undo_receipt(&source, &destination, ConflictAction::Overwrite)
            .unwrap();
        let receipt = receipt.unwrap();
        let (activity, error) = load_retained_move_activity();
        assert!(error.is_none(), "{error:?}");
        let selected = activity
            .iter()
            .find(|entry| {
                entry.plan.as_ref().is_some_and(|plan| {
                    plan.paths()
                        .contains(&std::fs::canonicalize(&destination).unwrap())
                })
            })
            .unwrap();
        let id = selected.transaction_id;
        let paths = selected.plan.as_ref().unwrap().paths().to_vec();
        app.retained_move_activity = activity;
        assert!(
            app.run_file_op_bound(
                FileCommand::RecoverRetainedMove { transaction_id: id },
                None,
                Vec::new(),
                None,
                None,
                None
            ),
            "{:?}",
            app.status_message
        );
        let record = app.operation_history.front().unwrap();
        assert_eq!(
            record.operation_paths,
            paths
                .into_iter()
                .map(OperationPath::write)
                .collect::<Vec<_>>()
        );
        // Native admissions return canonical paths; queue claims compare lexical
        // spellings, not filesystem aliases such as the runner's short TEMP path.
        let source_claim = std::fs::canonicalize(&source_parent)
            .unwrap()
            .join("entry.txt");
        let target = destination.join("entry.txt");
        let target_claim = std::fs::canonicalize(&target).unwrap();
        assert!(
            app.activity_paths_conflict(
                u64::MAX,
                &[(source_claim.as_path(), source_claim.as_path())]
            ),
            "requested {source_claim:?}; admitted {:?}",
            record.operation_paths
        );
        assert!(app.activity_paths_conflict(
            u64::MAX,
            &[(target_claim.as_path(), target_claim.as_path())]
        ));
        let result = app.op_rx.recv_timeout(Duration::from_secs(10)).unwrap();
        assert!(result.error.is_none(), "{:?}", result.error);
        app.op_tx.send(result).unwrap();
        app.poll_op_results();
        assert_eq!(
            app.operation_history.front().unwrap().status,
            OperationStatus::Completed
        );
        assert!(!app.activity_paths_conflict(
            u64::MAX,
            &[(source_claim.as_path(), source_claim.as_path())]
        ));
        assert!(!source.exists(), "forward recovery does not start Undo");
        assert_eq!(std::fs::read(target).unwrap(), b"selected source");
        DefaultPlatform.undo_move_with_receipt(&receipt).unwrap();
        assert_eq!(std::fs::read(source).unwrap(), b"selected source");
        assert_eq!(
            std::fs::read(destination.join("entry.txt")).unwrap(),
            b"displaced destination"
        );
        wait_for_retained_move_activity(&mut app);
    }

    #[cfg(target_os = "windows")]
    #[test]
    #[ignore = "requires the owned secondary volume and isolated native actor profile"]
    fn windows_move_cleanup_requires_captured_admission_and_uses_worker() {
        let profile = PathBuf::from(std::env::var_os("LOCALAPPDATA").unwrap());
        assert!(
            profile.starts_with(PathBuf::from(std::env::var_os("TEMP").unwrap())),
            "isolated actor profile required"
        );
        for cross in [false, true] {
            let primary = tempfile::tempdir().unwrap();
            let secondary = cross.then(|| {
                tempfile::tempdir_in(PathBuf::from(
                    std::env::var_os("OTTRIN_WINDOWS_CROSS_VOLUME_ROOT").unwrap(),
                ))
                .unwrap()
            });
            let source = primary.path().join("source/entry");
            let destination = secondary.as_ref().map_or_else(
                || primary.path().join("destination"),
                |s| s.path().join("destination"),
            );
            std::fs::create_dir(source.parent().unwrap()).unwrap();
            std::fs::create_dir(&destination).unwrap();
            std::fs::write(&source, b"selected-source").unwrap();
            std::fs::write(destination.join("entry"), b"displaced-target").unwrap();
            let (_, receipt) = DefaultPlatform
                .execute_move_with_undo_receipt(&source, &destination, ConflictAction::Overwrite)
                .unwrap();
            let receipt = receipt.unwrap();
            DefaultPlatform.undo_move_with_receipt(&receipt).unwrap();
            let mut app = OttrinApp::default();
            let (activity, error) = load_retained_move_activity();
            assert!(error.is_none(), "{error:?}");
            let row = activity
                .iter()
                .find(|row| {
                    row.plan
                        .as_ref()
                        .and_then(|plan| plan.undo_status_for(&receipt))
                        == Some(ottrin_platform::move_recovery::WindowsMoveUndoStatus::Complete)
                })
                .unwrap();
            let id = row.transaction_id;
            assert!(!row.plan.as_ref().unwrap().cleanup_complete());
            let preparation = ottrin_platform::WindowsMoveRecoveryPlan::capture_cleanup(id)
                .unwrap()
                .unwrap();
            let expected = preparation.paths().to_vec();
            let unknown = cross.then(|| {
                let private = expected
                    .iter()
                    .find(|p| {
                        p.file_name()
                            .is_some_and(|name| name.to_string_lossy().starts_with(".ottrin-move-"))
                    })
                    .unwrap();
                let path = private.join("unknown-user-file");
                std::fs::write(&path, b"keep-this").unwrap();
                path
            });
            app.retained_move_activity = activity;
            app.prepare_move_cleanup(id);
            assert!(app.move_cleanup_preparation.is_some());
            assert!(app.operation_history.is_empty());
            let deadline = Instant::now() + Duration::from_secs(10);
            while app.move_cleanup_preparation.is_some() {
                app.poll_move_cleanup_preparation();
                assert!(Instant::now() < deadline);
                std::thread::sleep(Duration::from_millis(1));
            }
            let record = app.operation_history.front().expect("queued cleanup");
            assert_eq!(record.title, "Clean up recovery records");
            assert_eq!(
                record.operation_paths,
                expected
                    .iter()
                    .cloned()
                    .map(OperationPath::write)
                    .collect::<Vec<_>>()
            );
            let bindings = capture_required_storage_bindings(
                expected.iter().map(|p| (p.as_path(), true)),
                &app.known_storage_locations,
            )
            .unwrap();
            assert!(!bindings.is_empty());
            if cross {
                assert!(bindings.len() >= 2);
            }
            assert!(app.activity_paths_conflict(
                u64::MAX,
                &[(destination.as_path(), destination.as_path())]
            ));
            let result = app.op_rx.recv_timeout(Duration::from_secs(10)).unwrap();
            assert!(result.error.is_none(), "{:?}", result.error);
            assert_eq!(result.warning.is_some(), cross);
            app.op_tx.send(result).unwrap();
            app.poll_op_results();
            assert_eq!(
                app.operation_history.front().unwrap().status,
                OperationStatus::Completed
            );
            assert!(!app.activity_paths_conflict(
                u64::MAX,
                &[(destination.as_path(), destination.as_path())]
            ));
            assert_eq!(std::fs::read(&source).unwrap(), b"selected-source");
            assert_eq!(
                std::fs::read(destination.join("entry")).unwrap(),
                b"displaced-target"
            );
            if let Some(unknown) = unknown {
                assert_eq!(std::fs::read(unknown).unwrap(), b"keep-this");
            }
            let current = ottrin_platform::WindowsMoveRecoveryPlan::capture(id).unwrap();
            assert!(current.cleanup_complete());
            assert_eq!(
                current.undo_status_for(&receipt),
                Some(ottrin_platform::move_recovery::WindowsMoveUndoStatus::Complete)
            );
            assert!(
                ottrin_platform::WindowsMoveRecoveryPlan::capture_cleanup(id)
                    .unwrap()
                    .is_none()
            );
        }
    }

    #[cfg(target_os = "windows")]
    fn assert_windows_move_undo_admission_tracks_renamed_parent_paths(cross_volume: bool) {
        for replace in [false, true] {
            let fixture = tempfile::Builder::new()
                .prefix("ottrin-parent-undo-ui-")
                .tempdir()
                .unwrap();
            let secondary = cross_volume.then(|| {
                tempfile::Builder::new()
                    .prefix("ottrin-parent-undo-ui-")
                    .tempdir_in(
                        std::env::var_os("OTTRIN_WINDOWS_CROSS_VOLUME_ROOT")
                            .expect("owned native second volume"),
                    )
                    .unwrap()
            });
            let destination_root = secondary
                .as_ref()
                .map_or(fixture.path(), |root| root.path());
            let before = fixture.path().join("source");
            let after = destination_root.join("destination");
            std::fs::create_dir(&before).unwrap();
            std::fs::create_dir(&after).unwrap();
            let source = before.join("entry");
            std::fs::write(&source, b"selected-original").unwrap();
            if replace {
                std::fs::write(after.join("entry"), b"displaced-original").unwrap();
            }
            let mut app = OttrinApp::default();
            let conflict = if replace {
                ConflictAction::Overwrite
            } else {
                ConflictAction::Skip
            };
            let origin_tab = app.state.active_tab().id;
            assert!(app.run_file_op_bound(
                FileCommand::Move {
                    sources: vec![source.clone()],
                    destination: after.clone(),
                    conflict
                },
                Some(origin_tab),
                Vec::new(),
                None,
                None,
                Some(conflict)
            ));
            let result = app.op_rx.recv_timeout(Duration::from_secs(10)).unwrap();
            assert!(result.error.is_none(), "{:?}", result.error);
            let id = result.op_id;
            app.op_tx.send(result).unwrap();
            app.poll_op_results();
            let current_before = fixture.path().join("renamed-source");
            let current_after = destination_root.join("renamed-destination");
            std::fs::rename(&before, &current_before).unwrap();
            std::fs::rename(&after, &current_after).unwrap();
            std::fs::create_dir(&before).unwrap();
            std::fs::create_dir(&after).unwrap();
            std::fs::write(before.join("entry"), b"foreign-source").unwrap();
            std::fs::write(after.join("entry"), b"foreign-destination").unwrap();
            let tab = app.state.active_tab_mut();
            tab.current_dir = current_before.clone();
            tab.view_mode = ViewMode::List;
            let tab_id = tab.id;
            app.refresh_active_tab();
            let listing_before = app.tab_ui[&tab_id].main.request_id;
            app.run_path_move_undo(id);
            assert!(
                app.native_undo_preparation.is_some(),
                "admission runs off the UI thread"
            );
            assert!(
                app.path_move_undo_rx.try_recv().is_err(),
                "no inverse before captured admission"
            );
            wait_for_native_undo_preparation(&mut app);
            let record = app
                .operation_history
                .iter()
                .find(|record| record.id == id)
                .unwrap();
            let OperationUndoReceipt::WindowsMove(plan) =
                &record.path_move_undo_token.as_ref().unwrap().receipt
            else {
                panic!("captured native Move plan");
            };
            assert!(
                plan.paths()
                    .contains(&std::fs::canonicalize(&current_before).unwrap())
            );
            assert!(
                plan.paths()
                    .contains(&std::fs::canonicalize(&current_after).unwrap())
            );
            // Keep the visible directory spelling for the selection assertion
            // below, but compare the same canonical claims native admission uses.
            let current_before_claim = std::fs::canonicalize(&current_before).unwrap();
            let before_claim = std::fs::canonicalize(&before).unwrap();
            assert!(
                app.activity_paths_conflict(
                    u64::MAX,
                    &[(
                        current_before_claim.as_path(),
                        current_before_claim.as_path()
                    )]
                ),
                "requested {current_before_claim:?}; admitted {:?}",
                plan.paths()
            );
            assert!(!app.activity_paths_conflict(
                u64::MAX,
                &[(before_claim.as_path(), before_claim.as_path())]
            ));
            let result = app
                .path_move_undo_rx
                .recv_timeout(Duration::from_secs(10))
                .unwrap();
            assert!(result.result.is_ok(), "{:?}", result.result);
            app.finish_path_move_undo(result.op_id, result.result, result.retryable);
            // Verify the actual refreshed rows, and finish background consumers
            // before releasing the fixture they read on Windows.
            let deadline = Instant::now() + Duration::from_secs(10);
            loop {
                app.poll_listing_results();
                app.poll_retained_move_activity();
                if !app.tab_ui[&tab_id].main.loading && !app.retained_move_activity_loader.pending {
                    break;
                }
                assert!(Instant::now() < deadline, "Undo refresh did not settle");
                std::thread::sleep(Duration::from_millis(1));
            }
            assert!(app.tab_ui[&tab_id].main.error.is_none());
            assert!(
                app.tab_ui[&tab_id]
                    .main
                    .entries
                    .iter()
                    .any(|entry| { entry.path == current_before.join("entry") }),
                "the restored entry is present in the refreshed visible listing"
            );
            assert!(
                app.tab_ui[&tab_id].main.request_id > listing_before,
                "the restored folder listing refreshes"
            );
            assert!(
                app.tab_ui[&tab_id]
                    .selected_paths
                    .contains(&current_before.join("entry")),
                "restored pointer selection uses the visible directory spelling"
            );
            assert!(!app.activity_paths_conflict(
                u64::MAX,
                &[(
                    current_before_claim.as_path(),
                    current_before_claim.as_path()
                )]
            ));
            assert_eq!(
                std::fs::read(current_before.join("entry")).unwrap(),
                b"selected-original"
            );
            if replace {
                assert_eq!(
                    std::fs::read(current_after.join("entry")).unwrap(),
                    b"displaced-original"
                );
            } else {
                assert!(!current_after.join("entry").exists());
            }
            assert_eq!(
                std::fs::read(before.join("entry")).unwrap(),
                b"foreign-source"
            );
            assert_eq!(
                std::fs::read(after.join("entry")).unwrap(),
                b"foreign-destination"
            );
        }
    }

