    #[test]
    fn quick_inspector_text_save_is_session_undoable() {
        let fixture = text_edit_fixture_root();
        let path = fixture.path().join("notes.txt");
        std::fs::write(&path, "original\n").expect("write source text");
        let Ok(session) = TextEditSession::open(&path) else {
            eprintln!("skipping Quick Inspector text-edit fixture: FIEMAP is unavailable");
            return;
        };

        let mut app = OttrinApp::default();
        app.preview.path = Some(path.clone());
        app.preview.text_editor = Some(PreviewTextEditor {
            session,
            buffer: "saved edit\n".to_string(),
            error: None,
            search_query: String::new(),
            search_next_char: 0,
            request_focus: true,
        });

        app.save_preview_text_edit();

        assert_eq!(
            std::fs::read_to_string(&path).unwrap(),
            "saved edit\n",
            "editor error: {:?}; activity: {:?}",
            app.preview
                .text_editor
                .as_ref()
                .and_then(|editor| editor.error.as_ref()),
            app.operation_history
        );
        let record = app.operation_history.front().expect("text edit activity");
        assert_eq!(record.title, "Edit text");
        assert_eq!(record.status, OperationStatus::Completed);
        assert_eq!(record.path_move_undo, Some(PathMoveUndoState::Available));
        assert_eq!(record.undo_kind, Some(PathMoveUndoKind::TextEdit));
        let op_id = record.id;

        app.run_path_move_undo(op_id);

        wait_for_native_undo_preparation(&mut app);
        for _ in 0..100 {
            app.poll_path_move_undo_results();
            if app
                .operation_history
                .front()
                .is_some_and(|record| record.path_move_undo == Some(PathMoveUndoState::Undone))
            {
                break;
            }
            std::thread::sleep(Duration::from_millis(10));
        }

        assert_eq!(std::fs::read_to_string(path).unwrap(), "original\n");
        let record = app.operation_history.front().unwrap();
        assert!(record.path_move_undo_token.is_none());
        assert_eq!(record.undo_kind(), PathMoveUndoKind::TextEdit);
        let ctx = Context::default();
        app.apply_theme_to_ctx(&ctx);
        let mut output = None;
        for _ in 0..3 {
            output = Some(ctx.run(
                egui::RawInput {
                    screen_rect: Some(Rect::from_min_size(
                        egui::Pos2::ZERO,
                        Vec2::new(500.0, 500.0),
                    )),
                    ..Default::default()
                },
                |ctx| {
                    egui::CentralPanel::default().show(ctx, |ui| {
                        app.render_activity_sidebar(ui);
                    });
                },
            ));
        }
        let output = output.unwrap();
        let labels: Vec<_> = output
            .shapes
            .iter()
            .filter_map(|shape| match &shape.shape {
                egui::Shape::Text(text) => Some(text.galley.job.text.as_str()),
                _ => None,
            })
            .collect();
        assert!(
            labels.contains(&"Text edit undone"),
            "Activity labels: {labels:?}"
        );
        assert!(!labels.contains(&"Rename undone"));
        assert_eq!(
            app.operation_history.front().unwrap().path_move_undo,
            Some(PathMoveUndoState::Undone)
        );
    }

    #[test]
    fn listing_completion_wakes_the_ui_without_input_or_polling() {
        let root = tempfile::tempdir().unwrap();
        std::fs::write(root.path().join("ready.txt"), "ready").unwrap();
        let mut app = OttrinApp::default();
        let key = ListingKey::TabMain(app.state.active_tab().id);
        // Drain constructor requests before binding the observed context.
        let barrier = app.request_listing(key, root.path().to_path_buf());
        loop {
            let result = app.listing_rx.recv_timeout(Duration::from_secs(2)).unwrap();
            if result.request_id == barrier {
                break;
            }
        }
        let ctx = Context::default();
        let (wake_tx, wake_rx) = mpsc::channel();
        ctx.set_request_repaint_callback(move |info| {
            wake_tx.send(info.delay).unwrap();
        });
        app.result_repaint.bind(&ctx);
        let request = app.request_listing(key, root.path().to_path_buf());
        assert_eq!(
            wake_rx.recv_timeout(Duration::from_secs(2)).unwrap(),
            Duration::ZERO
        );
        // The callback must follow result publication: no UI polling loop needed.
        let result = app
            .listing_rx
            .try_recv()
            .expect("listing already published at wake");
        assert_eq!(result.request_id, request);
        assert!(result.result.is_ok());
    }

    #[test]
    fn storage_location_refresh_wakes_an_idle_ui_within_the_bound() {
        let ctx = Context::default();
        let delays = Arc::new(std::sync::Mutex::new(Vec::new()));
        let captured_delays = Arc::clone(&delays);
        ctx.set_request_repaint_callback(move |info| {
            captured_delays.lock().unwrap().push(info.delay);
        });

        schedule_storage_location_refresh(&ctx);

        assert!(
            delays
                .lock()
                .unwrap()
                .iter()
                .any(|delay| *delay <= STORAGE_LOCATION_REFRESH_INTERVAL)
        );
    }

