    #[test]
    fn retained_move_scan_is_off_thread_and_coalesces_refreshes_without_stale_results() {
        let ui_thread = std::thread::current().id();
        let (entered_tx, entered_rx) = mpsc::channel();
        let (release_tx, release_rx) = mpsc::channel();
        let (exited_tx, exited_rx) = mpsc::channel();
        struct OnExit(Sender<()>);
        impl Drop for OnExit {
            fn drop(&mut self) {
                let _ = self.0.send(());
            }
        }
        let on_exit = OnExit(exited_tx);
        let mut scans = 0;
        let mut loader: RetainedActivityLoader<RetainedMoveSnapshot> =
            RetainedActivityLoader::spawn_with(move || {
                let _keep_until_worker_exits = &on_exit;
                scans += 1;
                entered_tx
                    .send((std::thread::current().id(), scans))
                    .unwrap();
                release_rx.recv_timeout(Duration::from_secs(5)).unwrap();
                (
                    vec![RetainedMoveActivity {
                        #[cfg(any(target_os = "linux", target_os = "windows"))]
                        plan: None,
                        transaction_id: [scans; 16],
                        phase: "published",
                        recovery: RetainedMoveRecovery::Unavailable,
                    }],
                    None,
                )
            });
        loader.request().unwrap();
        let (thread, scan) = entered_rx.recv_timeout(Duration::from_secs(5)).unwrap();
        assert_ne!(thread, ui_thread);
        assert_eq!(scan, 1);
        assert!(loader.poll().is_none()); // A blocked scan cannot block the UI.
        for _ in 0..100 {
            loader.request().unwrap();
        }
        release_tx.send(()).unwrap();
        let deadline = Instant::now() + Duration::from_secs(5);
        loop {
            assert!(
                loader.poll().is_none(),
                "superseded evidence reached the UI"
            );
            if let Ok((_, scan)) = entered_rx.try_recv() {
                assert_eq!(scan, 2);
                break;
            }
            assert!(Instant::now() < deadline);
            std::thread::yield_now();
        }
        release_tx.send(()).unwrap();
        let result = loop {
            if let Some(result) = loader.poll() {
                break result;
            }
            assert!(Instant::now() < deadline);
            std::thread::yield_now();
        };
        let result = result.unwrap();
        assert_eq!(result.0[0].transaction_id, [2; 16]);
        assert!(result.1.is_none());
        assert!(!loader.pending);
        assert!(entered_rx.try_recv().is_err()); // Only one replacement scan.
        drop(loader);
        exited_rx.recv_timeout(Duration::from_secs(5)).unwrap();
    }

    #[test]
    fn retained_move_loader_reports_worker_disconnect_instead_of_waiting_forever() {
        let (request_tx, request_rx) = mpsc::sync_channel(1);
        let (result_tx, result_rx) = mpsc::sync_channel(1);
        let mut loader: RetainedActivityLoader<RetainedMoveSnapshot> = RetainedActivityLoader {
            request_tx,
            result_rx,
            pending: false,
            refresh_again: false,
        };
        loader.request().unwrap();
        drop(result_tx);
        assert_eq!(loader.poll(), Some(Err("Retained Activity worker stopped")));
        assert!(!loader.pending);
        assert!(loader.poll().is_none());
        drop(request_rx);
        assert_eq!(
            loader.request(),
            Err("Retained Activity worker is unavailable")
        );
        assert!(!loader.pending);
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn restored_copy_activity_undo_handles_overlapping_items_in_one_batch() {
        let root = tempfile::tempdir().unwrap();
        let destination = root.path().join("destination");
        std::fs::create_dir(&destination).unwrap();
        let sources: Vec<_> = (0..3)
            .map(|version| {
                let directory = root.path().join(format!("source-{version}"));
                std::fs::create_dir(&directory).unwrap();
                let source = directory.join("item");
                std::fs::write(&source, format!("version-{version}")).unwrap();
                source
            })
            .collect();
        let batch = DefaultPlatform.execute_copy_batch_with_undo_receipts(
            &sources,
            &destination,
            ConflictAction::Overwrite,
            &mut |_| Ok(()),
        );
        assert!(batch.error.is_none(), "{:?}", batch.error);
        let ids: Vec<_> = batch
            .undo_receipts
            .iter()
            .map(|receipt| {
                receipt
                    .before_path()
                    .parent()
                    .unwrap()
                    .file_name()
                    .unwrap()
                    .to_str()
                    .unwrap()
                    .strip_prefix(".ottrin-txn-")
                    .unwrap()
                    .to_owned()
            })
            .collect();
        drop(batch);
        let discover = || {
            ottrin_platform::discover_retained_copy_transactions()
                .unwrap()
                .into_iter()
                .filter(|entry| ids.contains(&entry.transaction_id))
                .collect()
        };
        let groups = group_retained_copy_activity(discover());
        assert_eq!(groups.len(), 1);
        assert_eq!(groups[0].undo, PathMoveUndoState::Available);
        assert_eq!(groups[0].receipt.as_ref().unwrap().remaining(), 3);
        let mut app = OttrinApp::default();
        app.merge_retained_copy_activity(groups);
        assert_eq!(app.operation_history.len(), 1);
        let id = app.operation_history[0].id;
        app.run_path_move_undo(id);
        wait_for_native_undo_preparation(&mut app);
        let deadline = Instant::now() + Duration::from_secs(5);
        while matches!(
            app.operation_history[0].path_move_undo,
            Some(PathMoveUndoState::UndoQueued)
        ) {
            app.poll_path_move_undo_results();
            assert!(Instant::now() < deadline);
            std::thread::sleep(Duration::from_millis(1));
        }
        assert_eq!(
            app.operation_history[0].path_move_undo,
            Some(PathMoveUndoState::Undone)
        );
        assert!(!destination.join("item").exists());
        for (version, source) in sources.iter().enumerate() {
            assert_eq!(
                std::fs::read_to_string(source).unwrap(),
                format!("version-{version}")
            );
        }
        let completed = group_retained_copy_activity(discover());
        assert_eq!(completed[0].undo, PathMoveUndoState::Undone);
        assert!(completed[0].receipt.is_none());
        assert_eq!(completed[0].ownership.transactions.len(), 3);
        assert!(completed[0].detail.contains("3 already undone"));
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn restored_copy_activity_groups_undo_and_retains_completed_and_review_owners() {
        use ottrin_platform::CopyRecoveryEvidence;
        let root = tempfile::tempdir().unwrap();
        let destination = root.path().join("destination");
        std::fs::create_dir(&destination).unwrap();
        let sources: Vec<_> = ["first", "last"]
            .into_iter()
            .map(|name| {
                let source = root.path().join(name);
                std::fs::write(&source, name).unwrap();
                source
            })
            .collect();
        let batch = DefaultPlatform.execute_copy_batch_with_undo_receipts(
            &sources,
            &destination,
            ConflictAction::Skip,
            &mut |_| Ok(()),
        );
        assert!(batch.error.is_none(), "{:?}", batch.error);
        let ids: Vec<_> = batch
            .undo_receipts
            .iter()
            .map(|receipt| {
                receipt
                    .before_path()
                    .parent()
                    .unwrap()
                    .file_name()
                    .unwrap()
                    .to_str()
                    .unwrap()
                    .strip_prefix(".ottrin-txn-")
                    .unwrap()
                    .to_owned()
            })
            .collect();
        let discover = || {
            ottrin_platform::discover_retained_copy_transactions()
                .unwrap()
                .into_iter()
                .filter(|entry| ids.contains(&entry.transaction_id))
                .collect::<Vec<_>>()
        };
        let groups = group_retained_copy_activity(discover());
        assert_eq!(groups.len(), 1);
        assert_eq!(groups[0].undo, PathMoveUndoState::Available);
        assert_eq!(groups[0].receipt.as_ref().unwrap().remaining(), 2);
        let mut conflict = OttrinApp::default();
        conflict.queue_operation_record(FileCommand::Rename {
            source: destination.join("last"),
            new_name: "other".into(),
        });
        let token = restored_copy_token(groups[0].receipt.clone()).unwrap();
        assert!(conflict.path_move_undo_conflicts(u64::MAX, &token.receipt));
        let mut duplicate = discover();
        duplicate[1].operation.as_mut().unwrap().item_index =
            duplicate[0].operation.as_ref().unwrap().item_index;
        let rejected = group_retained_copy_activity(duplicate);
        assert!(matches!(
            rejected[0].undo,
            PathMoveUndoState::Unavailable { .. }
        ));
        assert!(rejected[0].receipt.is_none());
        let mut inconsistent = discover();
        inconsistent[1].operation.as_mut().unwrap().item_count += 1;
        assert!(matches!(
            group_retained_copy_activity(inconsistent)[0].undo,
            PathMoveUndoState::Unavailable { .. }
        ));
        let mut stale_snapshot = discover();
        stale_snapshot.pop();
        let rejected = group_retained_copy_activity(stale_snapshot);
        assert!(matches!(
            rejected[0].undo,
            PathMoveUndoState::Unavailable { .. }
        ));
        assert!(rejected[0].receipt.is_none());
        // Simulate an inverse interrupted after the final item completed.
        DefaultPlatform
            .undo_copy_with_receipt(batch.undo_receipts.last().unwrap(), &mut |_| Ok(()))
            .unwrap();
        let groups = group_retained_copy_activity(discover());
        assert_eq!(groups[0].receipt.as_ref().unwrap().remaining(), 1);
        assert_eq!(groups[0].undo, PathMoveUndoState::Available);
        let mut app = OttrinApp::default();
        let filter_ids = ids.clone();
        app.retained_copy_activity_loader = RetainedActivityLoader::spawn_with(move || {
            let (groups, error) = load_retained_copy_activity();
            (
                groups
                    .into_iter()
                    .filter(|group| {
                        group
                            .ownership
                            .transactions
                            .iter()
                            .any(|id| filter_ids.contains(id))
                    })
                    .collect(),
                error,
            )
        });
        app.refresh_retained_copy_activity();
        let deadline = Instant::now() + Duration::from_secs(5);
        while app.retained_copy_activity_loader.pending {
            app.poll_retained_copy_activity();
            assert!(Instant::now() < deadline);
            std::thread::sleep(Duration::from_millis(1));
        }
        assert!(app.retained_copy_activity_error.is_none());
        app.merge_retained_copy_activity(groups);
        assert_eq!(app.operation_history.len(), 1);
        app.state.tabs[0].current_dir = destination.clone();
        app.state.tabs[0].view_mode = ViewMode::List;
        app.refresh_active_tab();
        let tab_id = app.state.active_tab().id;
        let wait_listing = |app: &mut OttrinApp| {
            let deadline = Instant::now() + Duration::from_secs(5);
            while app
                .tab_ui
                .get(&tab_id)
                .is_some_and(|state| state.main.loading)
            {
                app.poll_listing_results();
                assert!(Instant::now() < deadline);
                std::thread::sleep(Duration::from_millis(1));
            }
        };
        wait_listing(&mut app);
        assert_eq!(app.tab_ui[&tab_id].main.entries.len(), 1);
        let record = &app.operation_history[0];
        assert!(!record.can_clear_history());
        let id = record.id;
        // Exercise the same asynchronous inverse path used by the Activity button.
        app.run_path_move_undo(id);
        wait_for_native_undo_preparation(&mut app);
        let deadline = Instant::now() + Duration::from_secs(5);
        while matches!(
            app.operation_history[0].path_move_undo,
            Some(PathMoveUndoState::UndoQueued)
        ) {
            app.poll_path_move_undo_results();
            assert!(Instant::now() < deadline);
            std::thread::sleep(Duration::from_millis(1));
        }
        assert_eq!(
            app.operation_history[0].path_move_undo,
            Some(PathMoveUndoState::Undone)
        );
        assert!(
            !app.retained_copy_activity_loader.pending,
            "successful Undo must not rescan all retained data"
        );
        assert!(app.operation_history[0].detail.contains("Undo complete"));
        wait_listing(&mut app);
        assert!(
            app.tab_ui[&tab_id].main.entries.is_empty(),
            "Undo must refresh the visible destination listing"
        );
        for name in ["first", "last"] {
            assert!(!destination.join(name).exists());
            assert_eq!(
                std::fs::read_to_string(root.path().join(name)).unwrap(),
                name
            );
        }
        let later_copy = DefaultPlatform.execute_copy_batch_with_undo_receipts(
            &sources,
            &destination,
            ConflictAction::Skip,
            &mut |_| Ok(()),
        );
        assert!(later_copy.error.is_none());
        assert_eq!(later_copy.undo_receipts.len(), 2);
        let completed = discover();
        assert!(
            completed.iter().all(|entry| entry.evidence
                == CopyRecoveryEvidence::UndoneRetainedObjectsAndContentsMatch)
        );
        let mut fresh = OttrinApp::default();
        fresh.merge_retained_copy_activity(group_retained_copy_activity(completed));
        assert_eq!(
            fresh.operation_history[0].path_move_undo,
            Some(PathMoveUndoState::Undone)
        );
        assert!(fresh.operation_history[0].path_move_undo_token.is_none());
        assert_eq!(
            fresh.operation_history[0].undo_kind(),
            PathMoveUndoKind::Copy
        );
        fresh.clear_finished_activity();
        assert_eq!(fresh.operation_history.len(), 1);
        let mut incomplete = group_retained_copy_activity(discover());
        incomplete[0].ownership.transactions.pop();
        app.operation_history[0].message = Some("old failure".into());
        app.merge_retained_copy_activity(incomplete);
        assert!(app.operation_history[0].message.is_none());
        assert_eq!(
            app.operation_history[0]
                .retained_copy
                .as_ref()
                .unwrap()
                .transactions
                .len(),
            2
        );
        assert_eq!(
            app.operation_history[0].status,
            OperationStatus::NeedsReview
        );
        // Loss of discovery evidence must disable Undo without losing its owner.
        app.merge_retained_copy_activity(Vec::new());
        assert!(matches!(
            app.operation_history[0].path_move_undo,
            Some(PathMoveUndoState::Unavailable { .. })
        ));
        app.clear_finished_activity();
        assert_eq!(app.operation_history.len(), 1);
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn restored_copy_undo_refreshes_its_blocked_predecessor() {
        let root = tempfile::tempdir().unwrap();
        let destination = root.path().join("destination");
        std::fs::create_dir(&destination).unwrap();
        let mut ids = Vec::new();
        for version in 0..2 {
            let directory = root.path().join(format!("source-{version}"));
            std::fs::create_dir(&directory).unwrap();
            let source = directory.join("item");
            std::fs::write(&source, format!("version-{version}")).unwrap();
            let receipt = DefaultPlatform
                .execute_copy_with_undo_receipt(
                    &source,
                    &destination,
                    ConflictAction::Overwrite,
                    &mut |_| Ok(()),
                )
                .unwrap()
                .unwrap();
            ids.push(
                receipt
                    .before_path()
                    .parent()
                    .unwrap()
                    .file_name()
                    .unwrap()
                    .to_str()
                    .unwrap()
                    .strip_prefix(".ottrin-txn-")
                    .unwrap()
                    .to_owned(),
            );
        }
        let mut app = OttrinApp::default();
        let filter_ids = ids.clone();
        app.retained_copy_activity_loader = RetainedActivityLoader::spawn_with(move || {
            let (groups, error) = load_retained_copy_activity();
            (
                groups
                    .into_iter()
                    .filter(|group| {
                        group
                            .ownership
                            .transactions
                            .iter()
                            .any(|id| filter_ids.contains(id))
                    })
                    .collect(),
                error,
            )
        });
        app.refresh_retained_copy_activity();
        let deadline = Instant::now() + Duration::from_secs(5);
        while app.retained_copy_activity_loader.pending {
            app.poll_retained_copy_activity();
            assert!(Instant::now() < deadline);
            std::thread::sleep(Duration::from_millis(1));
        }
        assert_eq!(app.operation_history.len(), 2);
        let older = app
            .operation_history
            .iter()
            .find(|record| {
                record
                    .retained_copy
                    .as_ref()
                    .unwrap()
                    .transactions
                    .contains(&ids[0])
            })
            .unwrap();
        assert_eq!(
            older.retained_copy.as_ref().unwrap().blocked_by,
            vec![ids[1].clone()]
        );
        assert!(older.path_move_undo_token.is_none());
        let newest = app
            .operation_history
            .iter()
            .find(|record| {
                record
                    .retained_copy
                    .as_ref()
                    .unwrap()
                    .transactions
                    .contains(&ids[1])
            })
            .unwrap()
            .id;
        app.run_path_move_undo(newest);
        wait_for_native_undo_preparation(&mut app);
        let deadline = Instant::now() + Duration::from_secs(5);
        loop {
            app.poll_path_move_undo_results();
            app.poll_retained_copy_activity();
            let older = app
                .operation_history
                .iter()
                .find(|record| {
                    record
                        .retained_copy
                        .as_ref()
                        .unwrap()
                        .transactions
                        .contains(&ids[0])
                })
                .unwrap();
            if older.path_move_undo == Some(PathMoveUndoState::Available) {
                break;
            }
            assert!(
                Instant::now() < deadline,
                "predecessor did not become undoable"
            );
            std::thread::sleep(Duration::from_millis(1));
        }
        assert_eq!(
            std::fs::read_to_string(destination.join("item")).unwrap(),
            "version-0"
        );
    }

    #[test]
    fn copy_activity_merge_preserves_session_state_and_defers_while_work_is_running() {
        let mut app = OttrinApp::default();
        let id = app.queue_activity_record_with_recoverability(
            "Copy",
            "session",
            OperationRecoverability::SessionTracked,
        );
        let group = RestoredCopyActivity {
            ownership: RetainedCopyOwnership {
                key: "operation:test".into(),
                transactions: vec!["test".into()],
                blocked_by: Vec::new(),
                restored: true,
                finalization: None,
                #[cfg(target_os = "windows")]
                recovery: None,
                #[cfg(target_os = "windows")]
                cleanup_phase: Some(ottrin_platform::WindowsCopyPhase::Completed),
                #[cfg(target_os = "windows")]
                recovery_location: None,
            },
            detail: "restored".into(),
            undo: PathMoveUndoState::Undone,
            receipt: None,
        };
        app.operation_history[0].retained_copy = Some(RetainedCopyOwnership {
            restored: false,
            ..group.ownership.clone()
        });
        app.pending_retained_copy_activity = Some(vec![group.clone()]);
        // Stop the real scan from overwriting this controlled queued result.
        app.retained_copy_activity_loader.pending = false;
        app.poll_retained_copy_activity();
        assert!(app.pending_retained_copy_activity.is_some());
        assert_eq!(app.operation_history[0].detail, "session");
        app.finish_operation_record(id, OperationStatus::Completed, None);
        app.poll_retained_copy_activity();
        assert!(app.pending_retained_copy_activity.is_none());
        assert_eq!(app.operation_history.len(), 1);
        assert_eq!(app.operation_history[0].detail, "session");
        assert!(app.operation_history[0].path_move_undo.is_none());
        assert!(!app.operation_history[0].can_clear_history());
        let mut restored = OttrinApp::default();
        restored.merge_retained_copy_activity(vec![group]);
        for _ in 0..120 {
            let id = restored.queue_activity_record_with_recoverability(
                "Information",
                "temporary",
                OperationRecoverability::Informational,
            );
            restored.finish_operation_record(id, OperationStatus::Completed, None);
        }
        restored.clear_finished_activity();
        assert_eq!(restored.operation_history.len(), 1);
        assert_eq!(
            restored.operation_history[0].title,
            "Copy from previous session"
        );
    }

    fn wait_for_retained_move_activity(app: &mut OttrinApp) {
        let deadline = Instant::now() + Duration::from_secs(5);
        while app.retained_move_activity_loader.pending {
            assert!(
                Instant::now() < deadline,
                "retained Move scan did not finish"
            );
            app.poll_retained_move_activity();
            std::thread::sleep(Duration::from_millis(1));
        }
    }

    // These use the real profile-wide recovery registry. Parallel tests create
    // and retire journals, so each case needs its own process/state root.
    fn private_activity_process(test: &str) -> bool {
        const CHILD: &str = "OTTRIN_TEST_PRIVATE_ACTIVITY";
        if std::env::var(CHILD).as_deref() == Ok(test) {
            return false;
        }
        struct Child(std::process::Child);
        impl Drop for Child {
            fn drop(&mut self) {
                if !matches!(self.0.try_wait(), Ok(Some(_))) {
                    let _ = self.0.kill();
                    let _ = self.0.wait();
                }
            }
        }
        let root = tempfile::tempdir().expect("private Activity profile");
        let stdout = root.path().join("activity.stdout");
        let stderr = root.path().join("activity.stderr");
        let mut command = std::process::Command::new(std::env::current_exe().unwrap());
        command
            .args(["--exact", &format!("tests::{test}"), "--nocapture"])
            .env(CHILD, test)
            .stdout(std::fs::File::create(&stdout).expect("Activity output"))
            .stderr(std::fs::File::create(&stderr).expect("Activity diagnostics"));
        for (key, name) in [
            ("HOME", "home"),
            ("USERPROFILE", "home"),
            ("XDG_STATE_HOME", "state"),
            ("XDG_CONFIG_HOME", "config"),
            ("XDG_CACHE_HOME", "cache"),
            ("XDG_DATA_HOME", "data"),
            ("APPDATA", "roaming"),
            ("LOCALAPPDATA", "local"),
        ] {
            let directory = root.path().join(name);
            std::fs::create_dir_all(&directory).unwrap();
            command.env(key, directory);
        }
        let mut child = Child(command.spawn().expect("start private Activity test"));
        let deadline = Instant::now() + Duration::from_secs(20);
        loop {
            if let Some(status) = child.0.try_wait().expect("poll private Activity test") {
                let read_output = |path: &Path| {
                    assert!(std::fs::metadata(path).unwrap().len() <= 1024 * 1024);
                    std::fs::read_to_string(path).unwrap()
                };
                let output = read_output(&stdout);
                let diagnostic = read_output(&stderr);
                assert!(
                    status.success(),
                    "private Activity test failed: {test}: {status}\n{output}\n{diagnostic}"
                );
                assert!(
                    output.contains("test result: ok. 1 passed; 0 failed; 0 ignored;"),
                    "private Activity case did not execute: {test}\n{output}\n{diagnostic}"
                );
                return true;
            }
            assert!(
                Instant::now() < deadline,
                "private Activity test timed out: {test}"
            );
            std::thread::sleep(Duration::from_millis(10));
        }
    }

