    #[test]
    fn right_arrow_enters_the_selected_miller_folder_in_one_action() {
        let root = std::env::temp_dir().join(format!(
            "ottrin-miller-right-entry-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("clock after epoch")
                .as_nanos(),
        ));
        let child = root.join("selected-child");
        std::fs::create_dir_all(&child).expect("create selected folder fixture");
        std::fs::write(child.join("alpha.txt"), "alpha").expect("write first child entry");
        std::fs::write(child.join("beta.txt"), "beta").expect("write second child entry");

        let mut app = OttrinApp::default();
        let tab_id = app.state.active_tab().id;
        app.state.active_tab_mut().view_mode = ViewMode::Miller;
        app.state.active_tab_mut().current_dir = root.clone();
        let entries = list_directory(&root, false).expect("list Miller fixture");
        let selected = entries
            .iter()
            .position(|entry| entry.path == child)
            .expect("selected child in fixture");
        {
            let ui = app.tab_ui.entry(tab_id).or_default();
            ui.main.dir = root.clone();
            ui.main.entries = entries;
            ui.main_sel = Some(selected);
            ui.miller_focus_dir = Some(root.clone());
        }

        assert!(app.navigate_miller_right(tab_id));
        assert_eq!(app.state.active_tab().current_dir, child);
        assert_eq!(
            app.tab_ui.get(&tab_id).and_then(|ui| ui.miller_focus_hint),
            Some(MillerFocusHint::CurrentDir)
        );

        let (columns, current_col) = app.build_miller_model(tab_id);
        assert_eq!(
            app.effective_miller_focus_col(tab_id, &columns, current_col),
            current_col,
            "Up/Down after entering must operate in the entered folder, not a stale ancestor column"
        );
        let entered_column = &columns[current_col];
        assert_eq!(entered_column.dir, child);
        let next = entered_column.entries.len().saturating_sub(1).min(1);
        app.set_miller_selection(
            tab_id,
            &entered_column.dir,
            &entered_column.entries,
            next,
            true,
        );
        assert_eq!(
            app.state.active_tab().current_dir,
            child,
            "vertical selection after Right must not navigate or fling the tab elsewhere"
        );

        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn right_arrow_selection_survives_async_listing_after_render() {
        let fixture = tempfile::tempdir().expect("fixture");
        let root = fixture.path().to_path_buf();
        let child = root.join("child");
        std::fs::create_dir_all(&child).expect("child");
        std::fs::write(child.join("alpha.txt"), "alpha").expect("file");
        let mut app = OttrinApp::default();
        let tab_id = app.state.active_tab().id;
        app.state.active_tab_mut().view_mode = ViewMode::Miller;
        app.state.active_tab_mut().current_dir = root.clone();
        let entries = list_directory(&root, false).expect("list");
        let selected = entries
            .iter()
            .position(|entry| entry.path == child)
            .expect("row");
        {
            let ui = app.tab_ui.entry(tab_id).or_default();
            ui.main.dir = root.clone();
            ui.main.entries = entries;
            ui.main_sel = Some(selected);
            ui.miller_focus_dir = Some(root);
        }
        assert!(app.navigate_miller_right(tab_id));
        let _ = app.build_miller_model(tab_id);
        assert!(!app.tab_ui[&tab_id].pending_select_first);
        for _ in 0..100 {
            app.poll_listing_results();
            if !app.tab_ui[&tab_id].main.loading {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
        assert!(!app.tab_ui[&tab_id].main.loading);
        assert!(
            app.tab_ui[&tab_id].main_sel.is_some(),
            "async response cleared selection"
        );
    }

    #[test]
    fn pointer_folder_entry_updates_miller_path_and_reveals_an_empty_destination() {
        let root = std::env::temp_dir().join(format!(
            "ottrin-miller-pointer-entry-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("clock after epoch")
                .as_nanos(),
        ));
        let source = root.join("source");
        let destination = source.join("empty-destination");
        std::fs::create_dir_all(&destination).expect("create empty destination fixture");

        let mut app = OttrinApp::default();
        let tab_id = app.state.active_tab().id;
        app.state.active_tab_mut().view_mode = ViewMode::Miller;
        app.state.active_tab_mut().current_dir = source.clone();

        app.navigate_miller_pointer_folder(tab_id, destination.clone());

        assert_eq!(
            app.state.tab_by_id(tab_id).map(|tab| &tab.current_dir),
            Some(&destination),
            "a primary Miller folder click must make the clicked folder active"
        );
        assert!(app.tab_ui.get(&tab_id).is_some_and(|ui| {
            ui.miller_reveal
                .as_ref()
                .is_some_and(|reveal| reveal.destination() == destination)
                && ui.miller_scroll_selected
        }));
        let (columns, current_col) = app.build_miller_model(tab_id);
        assert_eq!(columns[current_col].dir, destination);
        assert!(
            columns[current_col].entries.is_empty(),
            "the clicked empty folder must become a renderable current column"
        );

        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn pointer_history_reveal_consumes_the_first_rendered_destination_without_selection() {
        let root = std::env::temp_dir().join(format!(
            "ottrin-pointer-reveal-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("clock after epoch")
                .as_nanos(),
        ));
        let source = root.join("source");
        let destination = root.join("destination");
        std::fs::create_dir_all(&source).expect("create source fixture");
        std::fs::create_dir_all(&destination).expect("create destination fixture");
        std::fs::write(destination.join("later-unrelated.txt"), "present")
            .expect("seed nonempty destination");

        let mut app = OttrinApp::default();
        let tab_id = app.state.active_tab().id;
        {
            let tab = app.state.tab_by_id_mut(tab_id).expect("active tab");
            tab.view_mode = ViewMode::Miller;
            tab.current_dir = source.clone();
            tab.history_back.push(destination.clone());
        }
        assert!(app.pointer_navigate(tab_id, PointerNavigation::Back));

        let render_miller_frame = |app: &mut OttrinApp| {
            let ctx = Context::default();
            let input = egui::RawInput {
                screen_rect: Some(Rect::from_min_size(
                    egui::pos2(0.0, 0.0),
                    Vec2::new(800.0, 600.0),
                )),
                ..Default::default()
            };
            let _ = ctx.run(input, |ctx| {
                egui::CentralPanel::default().show(ctx, |ui| app.render_miller(ui, tab_id));
            });
        };

        render_miller_frame(&mut app);
        assert!(
            app.tab_ui
                .get(&tab_id)
                .is_some_and(|ui| ui.miller_reveal.is_none()),
            "a nonempty destination with no restored selection must consume its reveal on its first production render"
        );

        let _ = std::fs::remove_dir_all(root);
    }

