    #[test]
    fn refreshing_the_pointer_navigation_destination_cancels_its_reveal() {
        let root = std::env::temp_dir().join(format!(
            "ottrin-pointer-refresh-cancel-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("clock after epoch")
                .as_nanos(),
        ));
        let source = root.join("source");
        let destination = root.join("destination");
        std::fs::create_dir_all(&source).expect("create source fixture");
        std::fs::create_dir_all(&destination).expect("create destination fixture");

        let mut app = OttrinApp::default();
        let tab_id = app.state.active_tab().id;
        {
            let tab = app.state.tab_by_id_mut(tab_id).expect("active tab");
            tab.view_mode = ViewMode::Miller;
            tab.current_dir = source;
            tab.history_back.push(destination.clone());
        }
        assert!(app.pointer_navigate(tab_id, PointerNavigation::Back));
        assert!(
            app.tab_ui
                .get(&tab_id)
                .is_some_and(|ui| ui.miller_reveal.is_some())
        );

        app.refresh_tab(tab_id, destination);
        assert!(
            app.tab_ui
                .get(&tab_id)
                .is_none_or(|ui| ui.miller_reveal.is_none()),
            "same-path refresh must supersede the prior pointer reveal"
        );

        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn selected_view_is_restored_after_recreating_the_app() {
        let mut app = OttrinApp::default();
        let tab_id = app.state.active_tab().id;
        for view in [ViewMode::List, ViewMode::Miller, ViewMode::Grid] {
            app.set_tab_view_mode(tab_id, view);
            let reopened = OttrinApp::new_with_config_and_graphics_status(
                load_config(),
                GraphicsRuntimeStatus::default(),
            );
            assert_eq!(reopened.state.active_tab().view_mode, view);
            assert_eq!(reopened.state.config.default_view_mode, view);
        }
    }

    #[test]
    fn leaving_miller_or_closing_a_tab_discards_its_pointer_reveal_state() {
        let mut app = OttrinApp::default();
        let tab_id = app.state.active_tab().id;
        app.state.active_tab_mut().view_mode = ViewMode::Miller;
        assert!(app.pointer_navigate(tab_id, PointerNavigation::Up));
        assert!(
            app.tab_ui
                .get(&tab_id)
                .is_some_and(|ui| ui.miller_reveal.is_some())
        );

        app.set_tab_view_mode(tab_id, ViewMode::List);
        assert!(
            app.tab_ui
                .get(&tab_id)
                .is_none_or(|ui| ui.miller_reveal.is_none())
        );

        let closing_idx = app.state.new_tab(default_home_dir());
        let closing_id = app.state.tabs[closing_idx].id;
        app.tab_ui.entry(closing_id).or_default().miller_reveal = Some(MillerReveal {
            destination: default_home_dir(),
        });
        app.address_bars.entry(closing_id).or_default().editing = true;
        app.close_tab(closing_idx);
        assert!(
            !app.tab_ui.contains_key(&closing_id) && !app.address_bars.contains_key(&closing_id),
            "closing a tab must remove its retained UI state instead of preserving stale reveal intent"
        );
    }

    #[test]
    fn failed_miller_history_navigation_does_not_report_a_move() {
        let mut app = OttrinApp::default();

        assert!(!app.navigate_active_back());
        assert!(!app.navigate_active_forward());
    }

    #[test]
    fn pointer_history_navigation_reveals_only_the_moved_miller_tandem_tab() {
        let mut app = OttrinApp::default();
        let left_id = app.state.active_tab().id;
        let right_idx = app.state.new_tab(default_home_dir());
        let right_id = app.state.tabs[right_idx].id;
        assert!(app.state.activate_tandem(0, right_idx).is_some());
        app.state
            .tab_by_id_mut(left_id)
            .expect("left tab")
            .view_mode = ViewMode::Miller;
        app.state
            .tab_by_id_mut(right_id)
            .expect("right tab")
            .view_mode = ViewMode::Miller;
        app.state
            .tab_by_id_mut(left_id)
            .expect("left tab")
            .history_back
            .push(PathBuf::from("/"));

        assert!(app.pointer_navigate(left_id, PointerNavigation::Back));
        let left_ui = app.tab_ui.get(&left_id).expect("left tab UI state");
        assert!(left_ui.miller_reveal.is_some());
        assert!(left_ui.miller_scroll_selected);
        assert!(
            app.tab_ui
                .get(&right_id)
                .is_none_or(|ui| ui.miller_reveal.is_none() && !ui.miller_scroll_selected),
            "a Tandem navigation action must not leak reveal state into the opposite pane"
        );

        app.tab_ui.entry(left_id).or_default().miller_reveal = None;
        app.tab_ui
            .entry(left_id)
            .or_default()
            .miller_scroll_selected = false;
        assert!(app.pointer_navigate(left_id, PointerNavigation::Forward));
        assert!(
            app.tab_ui
                .get(&left_id)
                .is_some_and(|ui| ui.miller_reveal.is_some() && ui.miller_scroll_selected)
        );

        app.tab_ui.entry(left_id).or_default().miller_reveal = None;
        app.tab_ui
            .entry(left_id)
            .or_default()
            .miller_scroll_selected = false;
        assert!(app.pointer_navigate(left_id, PointerNavigation::Up));
        assert!(
            app.tab_ui
                .get(&left_id)
                .is_some_and(|ui| ui.miller_reveal.is_some() && ui.miller_scroll_selected)
        );

        app.tab_ui.entry(left_id).or_default().miller_reveal = None;
        app.tab_ui
            .entry(left_id)
            .or_default()
            .miller_scroll_selected = false;
        assert!(!app.pointer_navigate(left_id, PointerNavigation::Forward));
        assert!(
            app.tab_ui
                .get(&left_id)
                .is_some_and(|ui| ui.miller_reveal.is_none() && !ui.miller_scroll_selected),
            "failed history navigation must not leave a stale pointer-reveal request"
        );
    }

    #[test]
    fn failed_pointer_navigation_never_schedules_a_miller_reveal() {
        let mut app = OttrinApp::default();
        let tab_id = app.state.active_tab().id;
        app.state.active_tab_mut().view_mode = ViewMode::Miller;
        app.state.active_tab_mut().current_dir = PathBuf::from("/");

        for navigation in [
            PointerNavigation::Back,
            PointerNavigation::Forward,
            PointerNavigation::Up,
        ] {
            app.tab_ui.entry(tab_id).or_default().miller_reveal = Some(MillerReveal {
                destination: PathBuf::from("/stale-pointer-destination"),
            });
            app.tab_ui.entry(tab_id).or_default().miller_scroll_selected = false;

            assert!(!app.pointer_navigate(tab_id, navigation));
            assert!(
                app.tab_ui
                    .get(&tab_id)
                    .is_some_and(|ui| ui.miller_reveal.is_none() && !ui.miller_scroll_selected),
                "a failed pointer navigation must cancel, not preserve, an older destination reveal"
            );
        }
    }

    #[test]
    fn pointer_up_navigation_reveals_miller_but_not_list_or_grid_tabs() {
        let mut app = OttrinApp::default();
        let tab_id = app.state.active_tab().id;

        app.state.active_tab_mut().view_mode = ViewMode::Miller;
        assert!(app.pointer_navigate(tab_id, PointerNavigation::Up));
        assert!(
            app.tab_ui
                .get(&tab_id)
                .is_some_and(|ui| ui.miller_reveal.is_some() && ui.miller_scroll_selected)
        );

        let ctx = Context::default();
        let input = egui::RawInput {
            screen_rect: Some(Rect::from_min_size(
                egui::pos2(0.0, 0.0),
                Vec2::new(800.0, 600.0),
            )),
            ..Default::default()
        };
        let _ = ctx.run(input, |ctx| {
            egui::CentralPanel::default().show(ctx, |ui| app.render_miller(ui, tab_id));
        });
        assert!(
            app.tab_ui
                .get(&tab_id)
                .is_some_and(|ui| ui.miller_reveal.is_none()),
            "the parent listing with its restored child row must consume the first reveal"
        );

        for mode in [ViewMode::List, ViewMode::Grid] {
            app.state.active_tab_mut().view_mode = mode;
            app.state.active_tab_mut().current_dir = default_home_dir();
            app.tab_ui.entry(tab_id).or_default().miller_reveal = None;
            app.tab_ui.entry(tab_id).or_default().miller_scroll_selected = false;
            assert!(app.pointer_navigate(tab_id, PointerNavigation::Up));
            assert!(
                app.tab_ui
                    .get(&tab_id)
                    .is_none_or(|ui| ui.miller_reveal.is_none() && !ui.miller_scroll_selected),
                "{mode:?} pointer navigation must not schedule a Miller reveal"
            );
        }
    }

    #[test]
    fn miller_empty_caption_stays_inside_the_file_viewport_beside_a_panel() {
        let fixture = tempfile::tempdir().unwrap();
        let destination = fixture.path().join("home/destination");
        std::fs::create_dir_all(&destination).unwrap();
        let ctx = Context::default();
        let mut app = OttrinApp::default();
        app.state.active_tab_mut().current_dir = destination;
        app.state.config.miller_column_width_mode = MillerColumnWidthMode::Fixed;
        app.sidebar = SidebarSection::Activity;
        app.state.config.smart_panel_width = 420.0;
        let tab_id = app.state.active_tab().id;
        let (columns, current) = app.build_miller_model(tab_id);
        let before: f32 = columns[..current]
            .iter()
            .map(|col| {
                app.miller_column_width(&col.dir, &col.entries) + MILLER_COLUMN_DIVIDER_WIDTH
            })
            .sum();
        let viewport = Rect::from_min_size(egui::pos2(20.0, 20.0), Vec2::new(1060.0, 400.0));
        app.apply_theme_to_ctx(&ctx);
        let mut output = None;
        for _ in 0..3 {
            output = Some(ctx.run(
                egui::RawInput {
                    screen_rect: Some(Rect::from_min_size(
                        egui::pos2(0.0, 0.0),
                        Vec2::new(1100.0, 690.0),
                    )),
                    ..Default::default()
                },
                |ctx| {
                    egui::CentralPanel::default().show(ctx, |ui| {
                        let (file_rect, panel_rect) = app.compute_smart_panel_layout(viewport);
                        app.smart_panel_rect = Some(panel_rect);
                        ui.scope_builder(UiBuilder::new().max_rect(file_rect), |ui| {
                            let id = ui.make_persistent_id(egui::Id::new(("miller_h", tab_id)));
                            let mut state =
                                egui::scroll_area::State::load(ctx, id).unwrap_or_default();
                            state.offset.x = (before - 480.0).max(0.0);
                            state.store(ctx, id);
                            app.render_miller(ui, tab_id);
                        });
                    });
                },
            ));
        }
        let output = output.unwrap();
        let text = output
            .shapes
            .iter()
            .find_map(|shape| match &shape.shape {
                egui::Shape::Text(text) if text.galley.job.text == "This folder is empty" => {
                    Some(text)
                }
                _ => None,
            })
            .expect("current empty column caption");
        let bounds = text.galley.rect.translate(text.pos.to_vec2());
        let uncovered = Rect::from_min_max(
            viewport.min,
            egui::pos2(app.smart_panel_rect.unwrap().left(), viewport.bottom()),
        );
        assert!(
            uncovered.expand(1.0).contains_rect(bounds),
            "empty caption {bounds:?} escapes the file viewport {viewport:?}"
        );
        assert!(
            text.galley.rows.len() > 1,
            "partly visible column caption must wrap"
        );
    }

    #[test]
    fn empty_folder_message_fits_the_visible_part_of_a_scrolled_column() {
        for dark in [true, false] {
            for scale in [1.0, 1.35] {
                for (left, width) in [(20.0, 100.0), (160.0, 100.0), (20.0, 240.0)] {
                    let ctx = Context::default();
                    let mut app = OttrinApp::default();
                    app.colors = Colors::preset(ThemePreset::Ottrin, dark);
                    app.colors.font_scale = scale;
                    app.apply_theme_to_ctx(&ctx);
                    let c = app.colors;
                    let tab_id = app.state.active_tab().id;
                    let column =
                        Rect::from_min_size(egui::pos2(20.0, 20.0), Vec2::new(240.0, 400.0));
                    let visible =
                        Rect::from_min_size(egui::pos2(left, 20.0), Vec2::new(width, 400.0));
                    let output = ctx.run(Default::default(), |ctx| {
                        egui::CentralPanel::default().show(ctx, |ui| {
                            ui.scope_builder(UiBuilder::new().max_rect(column), |ui| {
                                ui.set_clip_rect(visible);
                                app.render_empty_folder_state(
                                    ui,
                                    tab_id,
                                    Path::new("/empty"),
                                    &c,
                                    false,
                                );
                            });
                        });
                    });
                    let text = output
                        .shapes
                        .iter()
                        .find_map(|shape| match &shape.shape {
                            egui::Shape::Text(text)
                                if text.galley.job.text == "This folder is empty" =>
                            {
                                Some(text)
                            }
                            _ => None,
                        })
                        .expect("empty folder caption is rendered");
                    let bounds = text.galley.rect.translate(text.pos.to_vec2());
                    assert!(
                        visible.expand(1.0).contains_rect(bounds),
                        "caption {bounds:?} exceeds visible column {visible:?}"
                    );
                    if width == 100.0 {
                        assert!(text.galley.rows.len() > 1, "narrow caption must wrap");
                    }
                }
            }
        }
    }

    #[test]
    fn shift_click_selects_exactly_two_tabs_without_entering_tandem() {
        assert_eq!(
            OttrinApp::tab_selection_after_click(&[], 7, 9, true),
            vec![7, 9]
        );
        assert_eq!(
            OttrinApp::tab_selection_after_click(&[7, 9], 7, 11, true),
            vec![7, 11],
            "a third Shift-click replaces the secondary choice"
        );
        assert_eq!(
            OttrinApp::tab_selection_after_click(&[7, 9], 7, 9, true),
            vec![7],
            "Shift-clicking a selected secondary tab toggles it off"
        );
        assert!(OttrinApp::tab_selection_after_click(&[7, 9], 7, 11, false).is_empty());
    }

