    #[test]
    fn sqlite_schedule_status_is_cached_until_explicit_refresh() {
        let mut cached = None;
        let mut probes = 0;

        for _ in 0..120 {
            let status = cached_sqlite_schedule_status(&mut cached, || {
                probes += 1;
                ottrin_search::LocateScheduleStatus {
                    source: "test".to_string(),
                    enabled: true,
                    detail: "cached".to_string(),
                }
            });
            assert!(status.enabled);
        }
        assert_eq!(probes, 1);

        cached = None;
        let _ = cached_sqlite_schedule_status(&mut cached, || {
            probes += 1;
            ottrin_search::LocateScheduleStatus {
                source: "test".to_string(),
                enabled: false,
                detail: "refreshed".to_string(),
            }
        });
        assert_eq!(probes, 2);
    }

